export interface GeneratedImage {
  id: string;
  url: string; // Base64 data URL
  prompt: string;
  timestamp: number;
  params: GenerationParams;
}

export interface GenerationParams {
  prompt: string;
  imageCount: number;
  seed: number;
  useRandomSeed: boolean;
  styleA: string;
  styleB: string;
  matrixX: number; // -1 to 1
  matrixY: number; // -1 to 1
  negativePrompts: string[];
  uploadedImage?: string; // Base64 data URL for editing
}

export enum StyleOption {
  NONE = "None",
  CYBERPUNK = "Cyberpunk",
  WATERCOLOR = "Watercolor",
  REALISTIC = "Photorealistic",
  SKETCH = "Pencil Sketch",
  RETRO = "Retro 80s",
  SURREAL = "Surrealism",
  PIXEL = "Pixel Art",
  IMPRESSIONIST = "Impressionist",
  NOIR = "Film Noir",
  ANIME = "Anime",
  OIL_PAINTING = "Oil Painting",
  CLAY = "Claymation"
}

export const NEGATIVE_PROMPTS_OPTIONS = [
  "Blurry",
  "Low Quality",
  "Distorted",
  "Bad Anatomy",
  "Text/Watermark",
  "Oversaturated"
];

import { GoogleGenAI } from "@google/genai";
import { GenerationParams, StyleOption } from "../types";

const getSystemInstruction = () => {
  return "You are an expert AI art director and image editor. Your goal is to interpret the user's prompt, style preferences, and uploaded images to generate high-quality visual outputs. When a user provides a matrix coordinate for styles, interpret coordinates (-1 to 1) as intensity or opposition. +1 is maximum intensity, -1 is maximum avoidance/opposition.";
};

// Helper to clean base64 string for API usage (remove data:image/png;base64, prefix)
const extractBase64Data = (dataUrl: string): string => {
  return dataUrl.split(',')[1] || "";
};

const getMimeType = (dataUrl: string): string => {
  const match = dataUrl.match(/^data:(.*);base64,/);
  return match ? match[1] : 'image/png';
}

const constructEnrichedPrompt = (params: GenerationParams): string => {
  const { prompt, styleA, styleB, matrixX, matrixY, negativePrompts, seed, useRandomSeed } = params;

  let enrichedPrompt = `${prompt}`;

  // Style Matrix Logic
  const describeInfluence = (style: string, value: number) => {
    if (style === StyleOption.NONE) return "";
    if (value > 0.1) return `strongly apply ${style} style (intensity ${Math.round(value * 100)}%)`;
    if (value < -0.1) return `ensure the image does NOT have ${style} style elements, strictly avoid ${style}`;
    return "";
  };

  const influenceA = describeInfluence(styleA, matrixX);
  const influenceB = describeInfluence(styleB, matrixY);

  if (influenceA) enrichedPrompt += `. ${influenceA}`;
  if (influenceB) enrichedPrompt += `. ${influenceB}`;

  // Negative Prompts
  if (negativePrompts.length > 0) {
    enrichedPrompt += `. Avoid the following: ${negativePrompts.join(", ")}.`;
  }

  // Seed (Note: Gemini API supports seed in config, but we can also mention it if needed for reproducibility in prompt engineering context, though config is better)
  // We will pass seed to the config object, not the text prompt.

  return enrichedPrompt;
};

export const generateImages = async (params: GenerationParams): Promise<string[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const finalPrompt = constructEnrichedPrompt(params);
  const results: string[] = [];

  // Parallel requests for multiple images since generateContent typically returns 1 image per call for this model
  const promises = Array.from({ length: params.imageCount }).map(async (_, index) => {

    // Slight variation in seed if multiple images are requested but user selected a specific seed,
    // otherwise they'd all be identical. 
    // If random seed is on, we don't pass a seed (let model decide) or generate a random one.
    // If specific seed is set, we increment it slightly for batch variety unless that's undesired.
    // Usually batch generation implies variety.
    const requestSeed = params.useRandomSeed ? undefined : (params.seed + index);

    const config = {
      seed: requestSeed,
      // We can't strictly enforce "negative prompt" in config for this model yet, handled in prompt text.
    };

    try {
      let response;

      const parts: any[] = [{ text: finalPrompt }];

      // Handle Image Editing (Image Input)
      if (params.uploadedImage) {
        parts.unshift({
          inlineData: {
            data: extractBase64Data(params.uploadedImage),
            mimeType: getMimeType(params.uploadedImage),
          }
        });
      }

      response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: parts
        },
        config: config
      });

      // Extract image from response
      if (response && response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts) {
         for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
               return `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`;
            }
         }
      }
      return null;
    } catch (error) {
      console.error("Error generating image:", error);
      return null;
    }
  });

  const generated = await Promise.all(promises);
  // Filter out failed requests
  return generated.filter((img): img is string => img !== null);
};

