import React, { useRef, useEffect, useState } from 'react';

interface MatrixPlotterProps {
    x: number; // -1 to 1
    y: number; // -1 to 1
    onChange: (x: number, y: number) => void;
    labelX: string;
    labelY: string;
}

export const MatrixPlotter: React.FC<MatrixPlotterProps> = ({ x, y, onChange, labelX, labelY }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [isDragging, setIsDragging] = useState(false);

    const handleInteraction = (clientX: number, clientY: number) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();

        let newX = (clientX - rect.left) / rect.width; // 0 to 1
        let newY = (clientY - rect.top) / rect.height; // 0 to 1

        // Clamp 0-1
        newX = Math.max(0, Math.min(1, newX));
        newY = Math.max(0, Math.min(1, newY));

        // Convert to -1 to 1 range
        // visual X: left (-1) to right (1)
        // visual Y: bottom (-1) to top (1) -> DOM Y is top (0) to bottom (1), so invert

        const coordX = (newX * 2) - 1;
        const coordY = -((newY * 2) - 1); // Invert Y so top is positive

        onChange(parseFloat(coordX.toFixed(2)), parseFloat(coordY.toFixed(2)));
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        setIsDragging(true);
        handleInteraction(e.clientX, e.clientY);
    };

    const handleMouseMove = (e: MouseEvent) => {
        if (isDragging) {
            handleInteraction(e.clientX, e.clientY);
        }
    };

    const handleMouseUp = () => {
        setIsDragging(false);
    };

    useEffect(() => {
        if (isDragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        } else {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging]);

    // Convert -1/1 back to % for display
    const percentX = ((x + 1) / 2) * 100;
    const percentY = ((-y + 1) / 2) * 100; // Invert Y back for DOM positioning (top=0)

    return (
        <div className="relative w-full aspect-square bg-zinc-900 rounded-lg border border-zinc-700 overflow-hidden select-none group">
            {/* Grid Lines */}
            <div className="absolute inset-0 pointer-events-none">
                <div className="absolute top-1/2 left-0 right-0 h-px bg-zinc-700" />
                <div className="absolute left-1/2 top-0 bottom-0 w-px bg-zinc-700" />
            </div>

            {/* Labels */}
            <div className="absolute top-2 right-2 text-[10px] text-green-500 font-mono pointer-events-none opacity-50">
                (+, +)
            </div>
            <div className="absolute bottom-2 left-2 text-[10px] text-red-500 font-mono pointer-events-none opacity-50">
                (-, -)
            </div>

            {/* Interactive Area */}
            <div 
                ref={containerRef}
                onMouseDown={handleMouseDown}
                className="absolute inset-0 cursor-crosshair active:cursor-grabbing"
            >
                {/* The Dot */}
                <div 
                    className="absolute w-4 h-4 bg-indigo-500 rounded-full shadow-lg shadow-indigo-500/50 border-2 border-white transform -translate-x-1/2 -translate-y-1/2 transition-transform duration-75 ease-out"
                    style={{ left: `${percentX}%`, top: `${percentY}%` }}
                />
            </div>

            {/* Live readout */}
            <div className="absolute bottom-0 right-0 bg-zinc-900/80 px-2 py-1 text-[10px] text-zinc-400 font-mono border-tl rounded-tl">
                X:{x.toFixed(2)} Y:{y.toFixed(2)}
            </div>
        </div>
    );
};

