import { GoogleGenAI } from "@google/genai";
import { GenerationParams, StyleOption, Point } from "../types";

// Helper to clean base64 string for API usage (remove data:image/png;base64, prefix)
const extractBase64Data = (dataUrl: string): string => {
  return dataUrl.split(',')[1] || "";
};

const getMimeType = (dataUrl: string): string => {
  const match = dataUrl.match(/^data:(.*);base64,/);
  return match ? match[1] : 'image/png';
}

const constructEnrichedPrompt = (params: GenerationParams, point: Point): string => {
  const { prompt, styleA, styleB, negativePrompts } = params;
  const { x: matrixX, y: matrixY } = point;

  let enrichedPrompt = `${prompt}`;

  // Style Matrix Logic
  const describeInfluence = (style: string, value: number) => {
    if (style === StyleOption.NONE) return "";
    if (value > 0.1) return `strongly apply ${style} style (intensity ${Math.round(value * 100)}%)`;
    if (value < -0.1) return `ensure the image does NOT have ${style} style elements, strictly avoid ${style}`;
    return "";
  };

  const influenceA = describeInfluence(styleA, matrixX);
  const influenceB = describeInfluence(styleB, matrixY);

  if (influenceA) enrichedPrompt += `. ${influenceA}`;
  if (influenceB) enrichedPrompt += `. ${influenceB}`;

  // Negative Prompts
  if (negativePrompts.length > 0) {
    enrichedPrompt += `. Avoid the following: ${negativePrompts.join(", ")}.`;
  }

  return enrichedPrompt;
};

interface GenerationResult {
    url: string;
    point: Point;
}

export const generateImages = async (params: GenerationParams): Promise<GenerationResult[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Determine the tasks (requests) to be made
  // If multiple points, 1 request per point.
  // If 1 point, params.imageCount requests for that point.
  const tasks: { point: Point; seed: number | undefined }[] = [];

  if (params.matrixPoints.length > 1) {
    // Multi-point mode: Generate one image per point
    params.matrixPoints.forEach((point, index) => {
        tasks.push({
            point,
            seed: params.useRandomSeed ? undefined : (params.seed + index)
        });
    });
  } else {
    // Single-point mode: Generate imageCount images for the single point
    const point = params.matrixPoints[0] || { x: 0, y: 0 };
    for (let i = 0; i < params.imageCount; i++) {
        tasks.push({
            point,
            seed: params.useRandomSeed ? undefined : (params.seed + i)
        });
    }
  }

  const promises = tasks.map(async (task) => {
    const finalPrompt = constructEnrichedPrompt(params, task.point);
    const config = { seed: task.seed };

    try {
      const parts: any[] = [{ text: finalPrompt }];

      if (params.uploadedImage) {
        parts.unshift({
          inlineData: {
            data: extractBase64Data(params.uploadedImage),
            mimeType: getMimeType(params.uploadedImage),
          }
        });
      }

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts },
        config
      });

      if (response && response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts) {
         for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
               return {
                 url: `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`,
                 point: task.point
               };
            }
         }
      }
      return null;
    } catch (error) {
      console.error("Error generating image:", error);
      return null;
    }
  });

  const generated = await Promise.all(promises);
  return generated.filter((res): res is GenerationResult => res !== null);
};

import React, { useRef, useEffect, useState } from 'react';
import { Point } from '../types';

interface MatrixPlotterProps {
    points: Point[];
    onChange: (points: Point[]) => void;
    labelX: string;
    labelY: string;
}

export const MatrixPlotter: React.FC<MatrixPlotterProps> = ({ points, onChange, labelX, labelY }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [isDragging, setIsDragging] = useState(false);

    const handleInteraction = (clientX: number, clientY: number) => {
        if (!containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();

        let newX = (clientX - rect.left) / rect.width; // 0 to 1
        let newY = (clientY - rect.top) / rect.height; // 0 to 1

        // Clamp 0-1
        newX = Math.max(0, Math.min(1, newX));
        newY = Math.max(0, Math.min(1, newY));

        // Convert to -1 to 1 range
        const coordX = parseFloat(((newX * 2) - 1).toFixed(2));
        const coordY = parseFloat((-((newY * 2) - 1)).toFixed(2)); // Invert Y so top is positive

        // Interaction always resets to a single point at the cursor location (Standard behavior for plotting tools)
        onChange([{ x: coordX, y: coordY }]);
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        setIsDragging(true);
        handleInteraction(e.clientX, e.clientY);
    };

    const handleMouseMove = (e: MouseEvent) => {
        if (isDragging) {
            handleInteraction(e.clientX, e.clientY);
        }
    };

    const handleMouseUp = () => {
        setIsDragging(false);
    };

    useEffect(() => {
        if (isDragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        } else {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging]);

    return (
        <div className="relative w-full aspect-square bg-zinc-900 rounded-lg border border-zinc-700 overflow-hidden select-none group">
            {/* Grid Lines */}
            <div className="absolute inset-0 pointer-events-none">
                <div className="absolute top-1/2 left-0 right-0 h-px bg-zinc-700" />
                <div className="absolute left-1/2 top-0 bottom-0 w-px bg-zinc-700" />
            </div>

            {/* Labels */}
            <div className="absolute top-2 right-2 text-[10px] text-green-500 font-mono pointer-events-none opacity-50">
                (+, +)
            </div>
            <div className="absolute bottom-2 left-2 text-[10px] text-red-500 font-mono pointer-events-none opacity-50">
                (-, -)
            </div>

            {/* Interactive Area */}
            <div 
                ref={containerRef}
                onMouseDown={handleMouseDown}
                className="absolute inset-0 cursor-crosshair active:cursor-grabbing"
            >
                {/* Render All Points */}
                {points.map((p, idx) => {
                    const percentX = ((p.x + 1) / 2) * 100;
                    const percentY = ((-p.y + 1) / 2) * 100;
                    const isMulti = points.length > 1;

                    return (
                        <div 
                            key={idx}
                            className={`absolute w-3 h-3 rounded-full transform -translate-x-1/2 -translate-y-1/2 transition-all duration-200 
                                ${isMulti ? 'bg-indigo-400/80 border border-white/50' : 'bg-indigo-500 shadow-lg shadow-indigo-500/50 border-2 border-white'}
                            `}
                            style={{ left: `${percentX}%`, top: `${percentY}%` }}
                        />
                    );
                })}
            </div>

            {/* Live readout (shows current cursor position if dragging, or first point if static) */}
            <div className="absolute bottom-0 right-0 bg-zinc-900/80 px-2 py-1 text-[10px] text-zinc-400 font-mono border-tl rounded-tl">
                {points.length > 1 ? `${points.length} Points` : `X:${points[0]?.x.toFixed(2)} Y:${points[0]?.y.toFixed(2)}`}
            </div>
        </div>
    );
};

import React from 'react';
import { GenerationParams, StyleOption, NEGATIVE_PROMPTS_OPTIONS, Point } from '../types';
import { Settings2, MinusCircle, Dice5, Sliders, RefreshCw, LayoutGrid, Square, Diamond, MousePointer2 } from 'lucide-react';
