interface SidebarProps {
  params: GenerationParams;
  setParams: React.Dispatch<React.SetStateAction<GenerationParams>>;
  isGenerating: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({ params, setParams, isGenerating }) => {

  const handleStyleChange = (key: 'styleA' | 'styleB', value: string) => {
    setParams(prev => ({ ...prev, [key]: value }));
  };

  const toggleNegativePrompt = (option: string) => {
    setParams(prev => {
      const current = prev.negativePrompts;
      if (current.includes(option)) {
        return { ...prev, negativePrompts: current.filter(o => o !== option) };
      } else {
        return { ...prev, negativePrompts: [...current, option] };
      }
    });
  };

  const setMatrixPattern = (type: 'single' | 'corners' | 'diamond' | 'grid') => {
      let newPoints: Point[] = [];
      switch (type) {
          case 'single':
              newPoints = [{ x: 0, y: 0 }];
              break;
          case 'corners':
              newPoints = [
                  { x: -0.9, y: 0.9 }, // Top Left (visual top is +y)
                  { x: 0.9, y: 0.9 },  // Top Right
                  { x: -0.9, y: -0.9 },// Bottom Left
                  { x: 0.9, y: -0.9 }  // Bottom Right
              ];
              break;
          case 'diamond':
              newPoints = [
                  { x: 0, y: 0.9 },  // Top
                  { x: 0.9, y: 0 },  // Right
                  { x: 0, y: -0.9 }, // Bottom
                  { x: -0.9, y: 0 }  // Left
              ];
              break;
          case 'grid':
              // Cross pattern
              newPoints = [
                { x: 0, y: 0 },
                { x: 0.8, y: 0.8 },
                { x: -0.8, y: 0.8 },
                { x: 0.8, y: -0.8 },
                { x: -0.8, y: -0.8 }
              ];
              break;
      }
      setParams(prev => ({ ...prev, matrixPoints: newPoints }));
  };

  const isMultiPoint = params.matrixPoints.length > 1;

  return (
    <div className="w-80 h-full bg-zinc-900 border-r border-zinc-800 flex flex-col overflow-y-auto p-4 shrink-0 scrollbar-hide">
      <div className="flex items-center gap-2 mb-6">
        <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center">
          <Settings2 className="w-5 h-5 text-white" />
        </div>
        <h2 className="text-lg font-bold text-zinc-100">Configuration</h2>
      </div>

      {/* Generation Settings */}
      <div className="space-y-6">

        {/* Count Slider - Disabled in Multi-point mode */}
        <div className={`space-y-2 transition-opacity ${isMultiPoint ? 'opacity-50 pointer-events-none' : ''}`}>
          <div className="flex justify-between text-sm text-zinc-400">
            <span>Image Count</span>
            <span className="text-indigo-400 font-mono">
                {isMultiPoint ? `${params.matrixPoints.length} (Matrix)` : params.imageCount}
            </span>
          </div>
          <input
            type="range"
            min="1"
            max="4"
            step="1"
            value={params.imageCount}
            onChange={(e) => setParams(prev => ({ ...prev, imageCount: parseInt(e.target.value) }))}
            className="w-full h-2 bg-zinc-800 rounded-lg appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400"
            disabled={isGenerating}
          />
          <div className="flex justify-between text-xs text-zinc-500 px-1">
            <span>1</span>
            <span>2</span>
            <span>3</span>
            <span>4</span>
          </div>
        </div>

        {/* Seed Config */}
        <div className="space-y-3 bg-zinc-800/30 p-3 rounded-xl border border-zinc-800">
            <div className="flex items-center justify-between">
                <label className="text-sm font-medium text-zinc-300 flex items-center gap-2">
                    <Dice5 className="w-4 h-4 text-emerald-500" />
                    Seed
                </label>
                <button 
                    onClick={() => setParams(prev => ({...prev, useRandomSeed: !prev.useRandomSeed}))}
                    className={`text-xs px-2 py-1 rounded transition-colors ${params.useRandomSeed ? 'bg-emerald-500/20 text-emerald-400' : 'bg-zinc-700 text-zinc-400'}`}
                >
                    {params.useRandomSeed ? 'Random' : 'Custom'}
                </button>
            </div>
            {!params.useRandomSeed && (
                <div className="flex items-center gap-2">
                    <input 
                        type="number" 
                        value={params.seed}
                        onChange={(e) => setParams(prev => ({...prev, seed: parseInt(e.target.value) || 0}))}
                        className="w-full bg-zinc-900 border border-zinc-700 rounded p-2 text-sm text-zinc-200 focus:outline-none focus:border-indigo-500"
                    />
                    <button 
                        onClick={() => setParams(prev => ({...prev, seed: Math.floor(Math.random() * 999999)}))}
                        className="p-2 hover:bg-zinc-700 rounded text-zinc-400"
                        title="Generate Random Seed"
                    >
                        <RefreshCw className="w-4 h-4" />
                    </button>
                </div>
            )}
        </div>

        {/* Style Matrix */}
        <div className="space-y-4 pt-2 border-t border-zinc-800">
            <div className="flex items-center gap-2 mb-1">
                <Sliders className="w-4 h-4 text-indigo-400" />
                <span className="text-sm font-semibold text-zinc-200">Style Matrix</span>
            </div>

            <div className="grid grid-cols-2 gap-2 mb-2">
                <div className="space-y-1">
                    <label className="text-xs text-zinc-500 uppercase font-bold">Axis X (Style A)</label>
                    <select 
                        value={params.styleA}
                        onChange={(e) => handleStyleChange('styleA', e.target.value)}
                        className="w-full bg-zinc-800 text-xs text-zinc-200 p-2 rounded border border-zinc-700 focus:border-indigo-500 outline-none"
                    >
                        {Object.values(StyleOption).map(s => <option key={s} value={s}>{s}</option>)}
