                    >
                        {Object.values(StyleOption).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
            </div>

            <MatrixPlotter 
                points={params.matrixPoints}
                onChange={(points) => setParams(prev => ({ ...prev, matrixPoints: points }))}
                labelX={params.styleA}
                labelY={params.styleB}
            />

            {/* Shape Presets */}
            <div className="grid grid-cols-4 gap-2">
                <button onClick={() => setMatrixPattern('single')} className="p-2 bg-zinc-800 hover:bg-zinc-700 rounded text-zinc-400 hover:text-white flex items-center justify-center" title="Single Point">
                    <MousePointer2 className="w-4 h-4" />
                </button>
                <button onClick={() => setMatrixPattern('corners')} className="p-2 bg-zinc-800 hover:bg-zinc-700 rounded text-zinc-400 hover:text-white flex items-center justify-center" title="Corners">
                    <Square className="w-4 h-4" />
                </button>
                <button onClick={() => setMatrixPattern('diamond')} className="p-2 bg-zinc-800 hover:bg-zinc-700 rounded text-zinc-400 hover:text-white flex items-center justify-center" title="Diamond">
                    <Diamond className="w-4 h-4" />
                </button>
                <button onClick={() => setMatrixPattern('grid')} className="p-2 bg-zinc-800 hover:bg-zinc-700 rounded text-zinc-400 hover:text-white flex items-center justify-center" title="Grid / Cross">
                    <LayoutGrid className="w-4 h-4" />
                </button>
            </div>
            {isMultiPoint && (
                <div className="text-[10px] text-zinc-500 text-center">
                    Generating {params.matrixPoints.length} images based on matrix points.
                </div>
            )}
        </div>

        {/* Negative Prompts */}
        <div className="space-y-3 pt-2 border-t border-zinc-800">
            <div className="flex items-center gap-2 mb-1">
                <MinusCircle className="w-4 h-4 text-red-400" />
                <span className="text-sm font-semibold text-zinc-200">Negative Filter</span>
            </div>
            <div className="flex flex-wrap gap-2">
                {NEGATIVE_PROMPTS_OPTIONS.map(opt => (
                    <button
                        key={opt}
                        onClick={() => toggleNegativePrompt(opt)}
                        className={`text-xs px-3 py-1.5 rounded-full border transition-all ${
                            params.negativePrompts.includes(opt)
                            ? 'bg-red-500/20 border-red-500/50 text-red-300'
                            : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:border-zinc-600'
