  const [params, setParams] = useState<GenerationParams>(DEFAULT_PARAMS);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [currentImage, setCurrentImage] = useState<GeneratedImage | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!params.prompt.trim() && !params.uploadedImage) {
        setError("Please enter a prompt or upload an image.");
        return;
    }

    setIsGenerating(true);
    setError(null);

    // If using random seed, generate it now for this batch so it's recorded in history
    const finalSeed = params.useRandomSeed ? Math.floor(Math.random() * 9999999) : params.seed;
    const generationParams = { ...params, seed: finalSeed };

    try {
      // Returns Array<{ url: string, point: Point }>
      const results = await generateImages(generationParams);

      if (results.length === 0) {
        throw new Error("No images generated. Please try again.");
      }

      const newImages: GeneratedImage[] = results.map(res => ({
        id: crypto.randomUUID(),
        url: res.url,
        prompt: params.prompt || "Image Edit",
        timestamp: Date.now(),
        params: generationParams,
        usedPoint: res.point
      }));

      setHistory(prev => [...prev, ...newImages]);
      setCurrentImage(newImages[0]); // View the first one immediately
    } catch (err: any) {
      setError(err.message || "Failed to generate image.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setParams(prev => ({ ...prev, uploadedImage: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const clearUpload = () => {
      setParams(prev => ({ ...prev, uploadedImage: undefined }));
  };

  return (
    <div className="flex h-screen w-screen bg-zinc-950 text-zinc-100 overflow-hidden">

      {/* Sidebar */}
      <Sidebar 
        params={params} 
        setParams={setParams} 
        isGenerating={isGenerating} 
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Top Bar / Header */}
        <div className="h-16 border-b border-zinc-800 flex items-center px-6 justify-between bg-zinc-900/50 backdrop-blur-sm">
            <div className="flex items-center gap-3">
                 <div className="w-8 h-8 bg-yellow-400 rounded-full flex items-center justify-center text-zinc-900 font-bold">
                    N
                 </div>
                 <h1 className="font-bold text-xl tracking-tight">Nano<span className="text-yellow-400">Studio</span></h1>
            </div>
            <div className="text-xs text-zinc-500 font-mono">
                Powered by Gemini 2.5 Flash Image
            </div>
        </div>

        {/* Viewport / Canvas */}
        <div className="flex-1 relative flex flex-col">

            {/* If there's a current image, show viewer, otherwise empty state or welcome */}
            {currentImage ? (
                <ImageViewer 
                    image={currentImage} 
                    onClose={() => setCurrentImage(null)} 
                />
            ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-zinc-600 p-8 text-center">
                    <div className="w-24 h-24 bg-zinc-900 rounded-2xl flex items-center justify-center mb-4 border border-zinc-800">
                        <ImageIcon className="w-10 h-10 opacity-50" />
                    </div>
                    <h3 className="text-xl font-medium text-zinc-300 mb-2">Ready to Create</h3>
                    <p className="max-w-md text-sm">Use the sidebar to configure styles, upload a reference image for editing, or simply type a prompt below.</p>
                </div>
            )}

            {/* Prompt Input Area - Floating at bottom of canvas */}
            <div className="p-6">
                <div className="max-w-4xl mx-auto flex flex-col gap-4">

                    {/* Upload Preview */}
                    {params.uploadedImage && (
                        <div className="relative w-24 h-24 group">
                             <img src={params.uploadedImage} className="w-full h-full object-cover rounded-lg border border-indigo-500/50" />
                             <button 
                                onClick={clearUpload}
                                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-lg hover:scale-110 transition"
                             >
                                <X className="w-3 h-3" />
                             </button>
                             <div className="absolute inset-0 flex items-center justify-center bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity rounded-lg pointer-events-none">
                                <span className="text-[10px] text-white font-medium">Reference</span>
                             </div>
                        </div>
                    )}

                    {/* Input Box */}
                    <div className="relative flex items-center gap-2 bg-zinc-900 p-2 rounded-xl border border-zinc-700 shadow-xl focus-within:border-indigo-500 focus-within:ring-1 focus-within:ring-indigo-500 transition-all">

                        {/* Upload Button */}
                        <label className="p-3 text-zinc-400 hover:text-white cursor-pointer hover:bg-zinc-800 rounded-lg transition-colors" title="Upload Image for Editing">
                            <Upload className="w-5 h-5" />
                            <input type="file" className="hidden" accept="image/*" onChange={handleFileUpload} />
                        </label>

                        <textarea
                            value={params.prompt}
                            onChange={(e) => setParams(prev => ({ ...prev, prompt: e.target.value }))}
                            placeholder={params.uploadedImage ? "Describe how to edit this image..." : "Describe the image you want to create..."}
                            className="flex-1 bg-transparent border-none focus:ring-0 text-zinc-100 placeholder-zinc-500 resize-none h-12 py-3"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    handleGenerate();
                                }
                            }}
                        />

                        <button
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className={`p-3 rounded-lg flex items-center gap-2 font-medium transition-all ${
                                isGenerating 
                                ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' 
                                : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-500/20'
                            }`}
                        >
                            {isGenerating ? (
                                <Loader2 className="w-5 h-5 animate-spin" />
                            ) : (
                                <>
                                    <span>Generate</span>
                                    <Wand2 className="w-4 h-4" />
                                </>
                            )}
                        </button>
                    </div>

                    {error && (
                        <div className="text-red-400 text-sm bg-red-400/10 p-3 rounded-lg border border-red-400/20">
                            Error: {error}
                        </div>
                    )}
                </div>
            </div>
        </div>

        {/* History Rail */}
        <HistoryStrip 
            images={history} 
            onSelect={(img) => setCurrentImage(img)}
            onDelete={(id) => {
                setHistory(prev => prev.filter(i => i.id !== id));
                if (currentImage?.id === id) setCurrentImage(null);
            }} 
        />
      </div>

    </div>
  );
};

