import React, { useRef, useEffect, useState } from 'react';
import { Point } from '../types';

interface MatrixPlotterProps {
    points: Point[];
    onChange: (points: Point[]) => void;
    labelX: string;
    labelY: string;
}

export const MatrixPlotter: React.FC<MatrixPlotterProps> = ({ points, onChange, labelX, labelY }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [draggingIndex, setDraggingIndex] = useState<number | null>(null);

    // Calculate coordinates in -1 to 1 space from mouse event
    const getCoords = (clientX: number, clientY: number) => {
        if (!containerRef.current) return null;
        const rect = containerRef.current.getBoundingClientRect();

        let newX = (clientX - rect.left) / rect.width;
        let newY = (clientY - rect.top) / rect.height;

        // Clamp to 0-1
        newX = Math.max(0, Math.min(1, newX));
        newY = Math.max(0, Math.min(1, newY));

        // Convert to -1 to 1 range
        const coordX = parseFloat(((newX * 2) - 1).toFixed(2));
        const coordY = parseFloat((-((newY * 2) - 1)).toFixed(2)); // Invert Y so top is positive
        return { x: coordX, y: coordY };
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        e.preventDefault(); // Prevent text selection
        const coords = getCoords(e.clientX, e.clientY);
        if (!coords) return;

        // If no points exist (shouldn't happen), create one
        if (points.length === 0) {
             onChange([coords]);
             setDraggingIndex(0);
             return;
        }

        // Find the closest point to the cursor
        let closestIndex = 0;
        let minDistance = Infinity;

        points.forEach((p, idx) => {
            // Calculate squared euclidean distance in the grid space
            const dist = Math.pow(p.x - coords.x, 2) + Math.pow(p.y - coords.y, 2);
            if (dist < minDistance) {
                minDistance = dist;
                closestIndex = idx;
            }
        });

        // Snap the closest point to the cursor immediately and start dragging
        const newPoints = [...points];
        newPoints[closestIndex] = coords;
        onChange(newPoints);
        setDraggingIndex(closestIndex);
    };

    const handleMouseMove = (e: MouseEvent) => {
        if (draggingIndex === null) return;

        const coords = getCoords(e.clientX, e.clientY);
        if (!coords) return;

        // Use the points array from the closure (the state when drag started).
        // Since we are overwriting the dragged index with absolute mouse coordinates,
        // and other points don't move, using the closure's 'points' is safe and correct.
        const newPoints = [...points];
        newPoints[draggingIndex] = coords;
        onChange(newPoints);
    };

    const handleMouseUp = () => {
        setDraggingIndex(null);
    };

    useEffect(() => {
        if (draggingIndex !== null) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [draggingIndex]); 

    return (
        <div className="relative w-full aspect-square bg-zinc-900 rounded-lg border border-zinc-700 overflow-hidden select-none group">
            {/* Grid Lines */}
            <div className="absolute inset-0 pointer-events-none">
                <div className="absolute top-1/2 left-0 right-0 h-px bg-zinc-700" />
                <div className="absolute left-1/2 top-0 bottom-0 w-px bg-zinc-700" />
            </div>

            {/* Labels */}
            <div className="absolute top-2 right-2 text-[10px] text-green-500 font-mono pointer-events-none opacity-50">
                (+, +)
            </div>
            <div className="absolute bottom-2 left-2 text-[10px] text-red-500 font-mono pointer-events-none opacity-50">
                (-, -)
            </div>

            {/* Interactive Area */}
            <div 
                ref={containerRef}
                onMouseDown={handleMouseDown}
                className="absolute inset-0 cursor-crosshair active:cursor-grabbing"
            >
                {/* Render All Points */}
                {points.map((p, idx) => {
                    const percentX = ((p.x + 1) / 2) * 100;
                    const percentY = ((-p.y + 1) / 2) * 100;
                    const isMulti = points.length > 1;
                    const isDraggingThis = idx === draggingIndex;

                    return (
                        <div 
                            key={idx}
                            className={`absolute rounded-full transform -translate-x-1/2 -translate-y-1/2 transition-shadow duration-150 
                                ${isDraggingThis ? 'w-4 h-4 z-10' : 'w-3 h-3 z-0'}
                                ${isMulti ? 'bg-indigo-400 border border-white/80' : 'bg-indigo-500 border-2 border-white'}
                                ${isDraggingThis ? 'shadow-[0_0_15px_rgba(99,102,241,0.8)] scale-110' : 'shadow-lg shadow-indigo-500/30'}
                            `}
                            style={{ left: `${percentX}%`, top: `${percentY}%` }}
                        />
                    );
                })}
            </div>

            {/* Live readout */}
            <div className="absolute bottom-0 right-0 bg-zinc-900/90 px-2 py-1 text-[10px] text-zinc-400 font-mono border-tl rounded-tl backdrop-blur-sm pointer-events-none">
                {draggingIndex !== null 
                    ? `Active: X:${points[draggingIndex].x.toFixed(2)} Y:${points[draggingIndex].y.toFixed(2)}` 
                    : points.length > 1 ? `${points.length} Points` : `X:${points[0]?.x.toFixed(2)} Y:${points[0]?.y.toFixed(2)}`
                }
            </div>
        </div>
    );
};

import React from 'react';
import { GenerationParams, StyleOption, NEGATIVE_PROMPTS_OPTIONS, Point } from '../types';
import { Settings2, MinusCircle, Dice5, Sliders, RefreshCw, LayoutGrid, Square, Diamond, MousePointer2, Move } from 'lucide-react';
