const constructEnrichedPrompt = (params: GenerationParams, point: Point): string => {
  const { prompt, styleA, styleB, negativePrompts } = params;
  const { x: matrixX, y: matrixY } = point;

  let enrichedPrompt = `Subject: ${prompt}.`;

  const getStyleInstruction = (style: string, intensity: number): string => {
    if (style === StyleOption.NONE || !STYLE_PROMPTS[style]) return "";

    // Ignore small values close to center to prevent noise
    if (Math.abs(intensity) < 0.15) return "";

    const keywords = STYLE_PROMPTS[style];

    if (intensity > 0) {
        // Positive Influence
        // We add keywords to the prompt to steer the generation
        if (intensity > 0.6) {
            return `Strongly apply style: ${style}. key visuals: ${keywords}. (Weight: High)`;
        } else {
             return `Blend with style: ${style}. key visuals: ${keywords}. (Weight: Medium)`;
        }
    } else {
        // Negative Influence (Avoidance)
        // explicitly tell the model to avoid these traits
        return `Strictly avoid ${style} style. Ensure image does NOT contain: ${keywords}.`;
    }
  };

  const instructionA = getStyleInstruction(styleA, matrixX);
  const instructionB = getStyleInstruction(styleB, matrixY);

  if (instructionA) enrichedPrompt += ` ${instructionA}`;
  if (instructionB) enrichedPrompt += ` ${instructionB}`;

  // Negative Prompts
  if (negativePrompts.length > 0) {
    enrichedPrompt += ` Negative constraints (avoid): ${negativePrompts.join(", ")}.`;
  }

  // Quality Boosters
  enrichedPrompt += " Image requirements: High fidelity, detailed texture, accurate lighting, aesthetically pleasing composition.";

  return enrichedPrompt;
};

interface GenerationResult {
    url: string;
    point: Point;
}

export const generateImages = async (params: GenerationParams): Promise<GenerationResult[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Determine the tasks (requests) to be made
  // If multiple points, 1 request per point.
  // If 1 point, params.imageCount requests for that point.
  const tasks: { point: Point; seed: number | undefined }[] = [];

  if (params.matrixPoints.length > 1) {
    // Multi-point mode: Generate one image per point
    params.matrixPoints.forEach((point, index) => {
        tasks.push({
            point,
            seed: params.useRandomSeed ? undefined : (params.seed + index)
        });
    });
  } else {
    // Single-point mode: Generate imageCount images for the single point
    const point = params.matrixPoints[0] || { x: 0, y: 0 };
    for (let i = 0; i < params.imageCount; i++) {
        tasks.push({
            point,
            seed: params.useRandomSeed ? undefined : (params.seed + i)
        });
    }
  }

  const promises = tasks.map(async (task) => {
    const finalPrompt = constructEnrichedPrompt(params, task.point);
    const config = { seed: task.seed };

    try {
      const parts: any[] = [{ text: finalPrompt }];

      if (params.uploadedImage) {
        parts.unshift({
          inlineData: {
            data: extractBase64Data(params.uploadedImage),
            mimeType: getMimeType(params.uploadedImage),
          }
        });
      }

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts },
        config
      });

      if (response && response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts) {
         for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
               return {
                 url: `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`,
                 point: task.point
               };
            }
         }
      }
      return null;
    } catch (error) {
      console.error("Error generating image:", error);
      return null;
    }
  });

  const generated = await Promise.all(promises);
  return generated.filter((res): res is GenerationResult => res !== null);
};

import React, { useState, useEffect } from 'react';
import { GeneratedImage } from '../types';
import { Download, X, Maximize2, Grid2X2 } from 'lucide-react';

interface ImageViewerProps {
    images: GeneratedImage[];
    onClose: () => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ images, onClose }) => {
    const [focusedIndex, setFocusedIndex] = useState<number | null>(null);

    // Reset focus when the image set changes completely
    useEffect(() => {
        setFocusedIndex(null);
    }, [images]);

    if (!images || images.length === 0) return null;

    const handleDownload = (img: GeneratedImage) => {
        const link = document.createElement('a');
        link.href = img.url;
        link.download = `nano-studio-${img.timestamp}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    // Determine viewing mode
    // If only 1 image exists, forces single view.
    // If multiple images exist, defaults to grid, unless focusedIndex is set.
    const isSingleView = images.length === 1 || focusedIndex !== null;
    const activeImage = images.length === 1 ? images[0] : (focusedIndex !== null ? images[focusedIndex] : null);

    // --- Single Image View ---
    if (isSingleView && activeImage) {
        return (
            <div className="flex-1 flex items-center justify-center bg-zinc-950/50 p-6 overflow-hidden relative animate-in fade-in duration-200">
                <div className="relative w-full max-w-5xl max-h-full flex flex-col shadow-2xl shadow-black/50 rounded-2xl overflow-hidden bg-zinc-900 border border-zinc-800">
                    {/* Toolbar */}
                    <div className="absolute top-4 right-4 z-10 flex gap-2">
                        {images.length > 1 && (
                            <button 
                                onClick={() => setFocusedIndex(null)}
                                className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                                title="Back to Grid"
                            >
                                <Grid2X2 className="w-5 h-5" />
                            </button>
                        )}
                        <button 
                            onClick={() => handleDownload(activeImage)}
                            className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Download"
                        >
                            <Download className="w-5 h-5" />
                        </button>
                        <button 
                            onClick={onClose}
                            className="p-2 bg-black/50 hover:bg-red-500/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Close View"
                        >
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    {/* Image Container */}
                    <div className="flex-1 overflow-hidden flex items-center justify-center bg-zinc-950/50 p-1">
                        <img 
                            src={activeImage.url} 
                            alt={activeImage.prompt} 
                            className="max-w-full max-h-full object-contain shadow-lg"
                        />
                    </div>

                    {/* Info Footer */}
                    <div className="bg-zinc-900 p-4 border-t border-zinc-800 shrink-0">
                        <p className="text-zinc-100 font-medium mb-1 truncate">{activeImage.prompt}</p>
                        <div className="flex flex-wrap gap-4 text-xs text-zinc-500 font-mono">
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Seed:</span> 
                                <span className="text-zinc-300">{activeImage.params.seed}</span>
                             </div>
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Styles:</span>
                                <span className="text-zinc-300">{activeImage.params.styleA} + {activeImage.params.styleB}</span>
                             </div>
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Point:</span>
                                <span className="text-indigo-400">[{activeImage.usedPoint.x}, {activeImage.usedPoint.y}]</span>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    // --- Grid View ---
    return (
        <div className="flex-1 flex flex-col p-6 overflow-hidden relative animate-in fade-in duration-300">
             <div className="absolute top-4 right-6 z-10">
                <button 
                    onClick={onClose}
                    className="p-2 bg-zinc-900/80 hover:bg-red-500/80 text-white rounded-lg backdrop-blur-sm transition-all border border-zinc-700 hover:border-red-500 shadow-lg"
                    title="Close Gallery"
                >
                    <X className="w-5 h-5" />
                </button>
            </div>

            <div className="flex-1 overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-zinc-700 scrollbar-track-transparent">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-6xl mx-auto h-full content-center py-8">
                    {images.map((img, idx) => (
                        <div 
                            key={img.id} 
                            className="group relative aspect-square bg-zinc-900 rounded-2xl overflow-hidden border border-zinc-800 hover:border-indigo-500/50 transition-all shadow-xl hover:shadow-2xl hover:shadow-indigo-500/10"
                        >
                            <img src={img.url} alt={img.prompt} className="w-full h-full object-cover" />

                            {/* Hover Overlay */}
                            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 flex flex-col justify-end p-5">
                                <div className="flex justify-end gap-2 mb-auto pt-2 translate-y-4 group-hover:translate-y-0 transition-transform duration-300">
