          <div className="flex justify-between text-sm text-zinc-400">
            <span>Image Count</span>
            <span className="text-indigo-400 font-mono">
                {isMultiPoint ? `${params.matrixPoints.length} (Matrix)` : params.imageCount}
            </span>
          </div>
          <input
            type="range"
