                            Error: {error}
                        </div>
                    )}
                </div>
            </div>
        </div>

        {/* History Rail */}
        <HistoryStrip 
            images={history} 
            onSelect={(img) => setCurrentBatch([img])}
            onDelete={(id) => {
                setHistory(prev => prev.filter(i => i.id !== id));
                setCurrentBatch(prev => prev.filter(i => i.id !== id));
            }} 
        />
      </div>

    </div>
  );
};

