                        className="w-full bg-zinc-800 text-xs text-zinc-200 p-2 rounded border border-zinc-700 focus:border-indigo-500 outline-none"
                    >
                        {Object.values(StyleOption).map(s => <option key={s} value={s}>{s}</option>)}
