                        }`}
                    >
                        {opt}
                    </button>
                ))}
            </div>
        </div>

      </div>
    </div>
  );
};

import React from 'react';
import { GeneratedImage } from '../types';
import { Trash2, Layers, Sparkles } from 'lucide-react';

interface HistoryStripProps {
    images: GeneratedImage[];
    onSelect: (image: GeneratedImage) => void;
    onDelete: (id: string) => void;
    onUseAsReference: (image: GeneratedImage) => void;
    onIterate: (image: GeneratedImage) => void;
}

export const HistoryStrip: React.FC<HistoryStripProps> = ({ images, onSelect, onDelete, onUseAsReference, onIterate }) => {
    if (images.length === 0) return null;

    const handleReferenceClick = (e: React.MouseEvent, img: GeneratedImage) => {
        e.stopPropagation();
        onUseAsReference(img);
    };

    const handleIterateClick = (e: React.MouseEvent, img: GeneratedImage) => {
        e.stopPropagation();
        onIterate(img);
    };

    return (
        <div className="h-32 md:h-40 w-full bg-zinc-900 border-t border-zinc-800 shrink-0 flex flex-col">
            <div className="px-4 py-2 text-xs font-semibold text-zinc-500 uppercase tracking-wider flex justify-between items-center">
                <span>History ({images.length})</span>
            </div>
            <div className="flex-1 overflow-x-auto overflow-y-hidden flex items-center gap-3 px-4 pb-4">
                {images.slice().reverse().map((img) => (
                    <div 
                        key={img.id} 
                        className="group relative h-24 md:h-28 aspect-square bg-zinc-800 rounded-lg overflow-hidden border border-zinc-700 hover:border-indigo-500 transition-colors shrink-0 cursor-pointer"
                        onClick={() => onSelect(img)}
                    >
                        <img 
                            src={img.url} 
                            alt={img.prompt} 
                            className="w-full h-full object-cover"
                        />
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                             <button 
                                onClick={(e) => handleReferenceClick(e, img)}
                                className="p-1.5 bg-blue-500/20 text-blue-400 rounded-full hover:bg-blue-500 hover:text-white transition"
                                title="Use as Reference"
                            >
                                <Layers className="w-4 h-4" />
                            </button>
                             <button 
                                onClick={(e) => handleIterateClick(e, img)}
                                className="p-1.5 bg-amber-500/20 text-amber-400 rounded-full hover:bg-amber-500 hover:text-white transition"
                                title="Iterate Variations"
                            >
                                <Sparkles className="w-4 h-4" />
                            </button>
                             <button 
                                onClick={(e) => { e.stopPropagation(); onDelete(img.id); }}
                                className="p-1.5 bg-red-500/20 text-red-400 rounded-full hover:bg-red-500 hover:text-white transition"
                                title="Delete"
                            >
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { GeneratedImage } from '../types';
import { Download, X, Maximize2, Grid2X2, Layers, Sparkles } from 'lucide-react';

interface ImageViewerProps {
    images: GeneratedImage[];
    onClose: () => void;
    onUseAsReference: (image: GeneratedImage) => void;
    onIterate: (image: GeneratedImage) => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ images, onClose, onUseAsReference, onIterate }) => {
    const [focusedIndex, setFocusedIndex] = useState<number | null>(null);

    // Reset focus when the image set changes completely
    useEffect(() => {
        setFocusedIndex(null);
    }, [images]);

    if (!images || images.length === 0) return null;

    const handleDownload = (img: GeneratedImage) => {
        const link = document.createElement('a');
        link.href = img.url;
        link.download = `nano-studio-${img.timestamp}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleReferenceClick = (img: GeneratedImage) => {
        onUseAsReference(img);
        onClose(); // Close the viewer to go back to the prompt screen
    };

    // Determine viewing mode
    // If only 1 image exists, forces single view.
    // If multiple images exist, defaults to grid, unless focusedIndex is set.
    const isSingleView = images.length === 1 || focusedIndex !== null;
    const activeImage = images.length === 1 ? images[0] : (focusedIndex !== null ? images[focusedIndex] : null);

    // --- Single Image View ---
    if (isSingleView && activeImage) {
        return (
            <div className="flex-1 flex items-center justify-center bg-zinc-950/50 p-2 sm:p-4 md:p-6 overflow-hidden relative animate-in fade-in duration-200">
                <div className="relative w-full max-w-5xl max-h-full flex flex-col shadow-2xl shadow-black/50 rounded-2xl overflow-hidden bg-zinc-900 border border-zinc-800">
                    {/* Toolbar */}
                    <div className="absolute top-4 right-4 z-10 flex gap-2">
                        {images.length > 1 && (
                            <button 
                                onClick={() => setFocusedIndex(null)}
                                className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                                title="Back to Grid"
                            >
                                <Grid2X2 className="w-5 h-5" />
                            </button>
                        )}
                         <button 
                            onClick={() => handleReferenceClick(activeImage)}
                            className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Use as Reference"
                        >
                            <Layers className="w-5 h-5" />
                        </button>
                         <button 
                            onClick={() => onIterate(activeImage)}
                            className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Iterate Variations"
                        >
                            <Sparkles className="w-5 h-5" />
                        </button>
                        <button 
                            onClick={() => handleDownload(activeImage)}
                            className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Download"
                        >
                            <Download className="w-5 h-5" />
                        </button>
                        <button 
                            onClick={onClose}
                            className="p-2 bg-black/50 hover:bg-red-500/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Close View"
                        >
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    {/* Image Container */}
                    <div className="flex-1 overflow-hidden flex items-center justify-center bg-zinc-950/50 p-1">
                        <img 
                            src={activeImage.url} 
                            alt={activeImage.prompt} 
                            className="max-w-full max-h-full object-contain shadow-lg"
                        />
                    </div>

                    {/* Info Footer */}
                    <div className="bg-zinc-900 p-4 border-t border-zinc-800 shrink-0">
                        <p className="text-zinc-100 font-medium mb-1 truncate">{activeImage.prompt}</p>
                        <div className="flex flex-wrap gap-4 text-xs text-zinc-500 font-mono">
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Seed:</span> 
                                <span className="text-zinc-300">{activeImage.params.seed}</span>
                             </div>
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Styles:</span>
                                <span className="text-zinc-300">{activeImage.params.styleA} + {activeImage.params.styleB}</span>
                             </div>
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Point:</span>
                                <span className="text-indigo-400">[{activeImage.usedPoint.x}, {activeImage.usedPoint.y}]</span>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    // --- Grid View ---
    return (
        <div className="flex-1 flex flex-col p-4 md:p-6 overflow-hidden relative animate-in fade-in duration-300">
             <div className="absolute top-4 right-4 md:right-6 z-10">
                <button 
                    onClick={onClose}
                    className="p-2 bg-zinc-900/80 hover:bg-red-500/80 text-white rounded-lg backdrop-blur-sm transition-all border border-zinc-700 hover:border-red-500 shadow-lg"
                    title="Close Gallery"
                >
                    <X className="w-5 h-5" />
                </button>
            </div>

            <div className="flex-1 overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-zinc-700 scrollbar-track-transparent">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 max-w-6xl mx-auto h-full content-start py-8">
                    {images.map((img, idx) => (
                        <div 
                            key={img.id} 
                            className="group relative aspect-square bg-zinc-900 rounded-2xl overflow-hidden border border-zinc-800 hover:border-indigo-500/50 transition-all shadow-xl hover:shadow-2xl hover:shadow-indigo-500/10"
                        >
                            <img src={img.url} alt={img.prompt} className="w-full h-full object-cover" />

                            {/* Hover Overlay */}
                            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 flex flex-col justify-end p-5">
                                <div className="flex justify-end gap-2 mb-auto pt-2 translate-y-4 group-hover:translate-y-0 transition-transform duration-300">
                                     <button 
                                        onClick={() => setFocusedIndex(idx)}
                                        className="p-2.5 bg-black/60 hover:bg-indigo-600 text-white rounded-xl backdrop-blur-md transition-all border border-white/10"
                                        title="Maximize"
                                    >
                                        <Maximize2 className="w-5 h-5" />
                                    </button>
                                     <button 
                                        onClick={() => handleReferenceClick(img)}
                                        className="p-2.5 bg-black/60 hover:bg-blue-600 text-white rounded-xl backdrop-blur-md transition-all border border-white/10"
                                        title="Use as Reference"
                                    >
                                        <Layers className="w-5 h-5" />
                                    </button>
                                     <button 
                                        onClick={() => onIterate(img)}
                                        className="p-2.5 bg-black/60 hover:bg-amber-500 text-white rounded-xl backdrop-blur-md transition-all border border-white/10"
                                        title="Iterate Variations"
                                    >
                                        <Sparkles className="w-5 h-5" />
                                    </button>
                                     <button 
                                        onClick={() => handleDownload(img)}
                                        className="p-2.5 bg-black/60 hover:bg-emerald-600 text-white rounded-xl backdrop-blur-md transition-all border border-white/10"
                                        title="Download"
                                    >
                                        <Download className="w-5 h-5" />
                                    </button>
                                </div>
                                <div className="transform translate-y-2 group-hover:translate-y-0 transition-transform duration-300">
                                    <div className="flex items-center gap-2 mb-2">
                                        <span className="px-2 py-0.5 rounded-md bg-white/10 text-[10px] text-zinc-300 font-mono border border-white/5">
                                            {img.params.styleA}
                                        </span>
                                        <span className="px-2 py-0.5 rounded-md bg-white/10 text-[10px] text-zinc-300 font-mono border border-white/5">
                                            {img.params.styleB}
                                        </span>
                                    </div>
                                    <div className="text-sm font-medium text-white line-clamp-1 opacity-90">{img.prompt}</div>
                                </div>
                            </div>

                            {/* Always visible coordinate badge */}
                            <div className="absolute top-3 left-3 px-2 py-1 rounded bg-black/40 backdrop-blur-sm border border-white/10 text-[10px] text-zinc-400 font-mono opacity-60 group-hover:opacity-0 transition-opacity">
                                [{img.usedPoint.x}, {img.usedPoint.y}]
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { HistoryStrip } from './components/HistoryStrip';
import { ImageViewer } from './components/ImageViewer';
import { generateImages } from './services/geminiService';
import { GeneratedImage, GenerationParams, StyleOption, ModelOption, ColorPalette } from './types';
import { Wand2, Loader2, Upload, X, Image as ImageIcon, Menu } from 'lucide-react';

const DEFAULT_PARAMS: GenerationParams = {
  prompt: "",
  imageCount: 1,
  seed: Math.floor(Math.random() * 1000000),
  useRandomSeed: true,
  styleA: StyleOption.CYBERPUNK,
  styleB: StyleOption.REALISTIC,
  matrixPoints: [{ x: 0.5, y: 0.5 }], // Default to single point
  negativePrompts: [],
  uploadedImage: undefined,
  model: ModelOption.FLASH,
  colorPalette: ColorPalette.NONE
};

const App: React.FC = () => {
  const [params, setParams] = useState<GenerationParams>(DEFAULT_PARAMS);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [currentBatch, setCurrentBatch] = useState<GeneratedImage[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const handleGenerate = async (overrideParams?: Partial<GenerationParams>) => {
    const currentParams = { ...params, ...overrideParams };

    if (!currentParams.prompt.trim() && !currentParams.uploadedImage) {
        setError("Please enter a prompt or upload an image.");
        return;
    }

    setIsGenerating(true);
    setError(null);
    if (isSidebarOpen) setIsSidebarOpen(false);

    const finalSeed = currentParams.useRandomSeed ? Math.floor(Math.random() * 9999999) : currentParams.seed;
    const generationParams = { ...currentParams, seed: finalSeed };

    // Update the main params state if we're doing a manual generation
    if (!overrideParams) {
        setParams(generationParams);
    }

    try {
      const results = await generateImages(generationParams);

      if (results.length === 0) {
        throw new Error("No images generated. Please try again.");
      }

      const newImages: GeneratedImage[] = results.map(res => ({
        id: crypto.randomUUID(),
        url: res.url,
        prompt: generationParams.prompt || "Image Edit",
        timestamp: Date.now(),
        params: generationParams,
        usedPoint: res.point
      }));

      setHistory(prev => [...newImages, ...prev]);
      setCurrentBatch(newImages); 
    } catch (err: any) {
      setError(err.message || "Failed to generate image.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleIterate = (image: GeneratedImage) => {
      const iterationParams = { ...image.params, useRandomSeed: true };
      setParams(iterationParams); // Update sidebar UI to reflect the change
      handleGenerate(iterationParams);
  };

  const handleUseAsReference = (image: GeneratedImage) => {
      // Restore all parameters from the selected image and set its URL as the uploaded image
      setParams({ ...image.params, uploadedImage: image.url });
      // Clear the current view to return to the prompt input
      setCurrentBatch([]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setParams(prev => ({ ...prev, uploadedImage: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const clearUpload = () => {
      setParams(prev => ({ ...prev, uploadedImage: undefined }));
  };

  return (
    <div className="flex h-screen w-screen bg-zinc-950 text-zinc-100 overflow-hidden">

      {/* Backdrop for mobile sidebar */}
      {isSidebarOpen && (
        <div 
            className="fixed inset-0 bg-black/60 z-40 md:hidden"
            onClick={() => setIsSidebarOpen(false)}
            aria-hidden="true"
        />
      )}

      {/* Sidebar */}
      <Sidebar 
        params={params} 
        setParams={setParams} 
        isGenerating={isGenerating}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Top Bar / Header */}
        <div className="h-16 border-b border-zinc-800 flex items-center px-4 md:px-6 justify-between bg-zinc-900/50 backdrop-blur-sm shrink-0">
            <div className="flex items-center gap-2 md:gap-3">
                 <button 
                    onClick={() => setIsSidebarOpen(true)}
                    className="md:hidden p-2 -ml-2 text-zinc-400 hover:text-white"
                    aria-label="Open settings menu"
                 >
                    <Menu className="w-6 h-6" />
                 </button>
                 <div className="w-8 h-8 bg-yellow-400 rounded-full flex items-center justify-center text-zinc-900 font-bold shrink-0">
                    N
                 </div>
                 <h1 className="font-bold text-xl tracking-tight hidden sm:block">Nano<span className="text-yellow-400">Studio</span></h1>
            </div>
            <div className="text-xs text-zinc-500 font-mono hidden md:block">
                Powered by {params.model}
            </div>
        </div>

        {/* Viewport / Canvas */}
        <div className="flex-1 relative flex flex-col">

            {currentBatch.length > 0 ? (
                <ImageViewer 
                    images={currentBatch} 
                    onClose={() => setCurrentBatch([])} 
                    onIterate={handleIterate}
                    onUseAsReference={handleUseAsReference}
                />
            ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-zinc-600 p-8 text-center animate-in fade-in zoom-in duration-500">
                    <div className="w-24 h-24 bg-zinc-900/50 rounded-3xl flex items-center justify-center mb-6 border border-zinc-800 shadow-xl shadow-black/20">
                        <ImageIcon className="w-10 h-10 opacity-30" />
                    </div>
                    <h3 className="text-2xl font-semibold text-zinc-200 mb-3 tracking-tight">Ready to Create</h3>
                    <p className="max-w-md text-zinc-500 leading-relaxed">
                        Configure your styles in the sidebar, or simply describe what you want to see below.
                        <br/><span className="text-xs opacity-50 mt-2 block">Try the Style Matrix for advanced blending.</span>
                    </p>
                </div>
            )}

            {/* Prompt Input Area - Floating at bottom of canvas */}
            <div className="p-4 md:p-6 shrink-0 z-20">
                <div className="max-w-4xl mx-auto flex flex-col gap-4">

                    {/* Upload Preview */}
                    {params.uploadedImage && (
                        <div className="relative w-24 h-24 group">
                             <img src={params.uploadedImage} className="w-full h-full object-cover rounded-xl border border-indigo-500/50 shadow-lg" alt="Reference" />
                             <button 
                                onClick={clearUpload}
                                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1.5 shadow-lg hover:scale-110 transition border border-zinc-900"
                             >
                                <X className="w-3 h-3" />
                             </button>
                             <div className="absolute inset-0 flex items-center justify-center bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity rounded-xl pointer-events-none backdrop-blur-sm">
                                <span className="text-[10px] text-white font-medium">Reference</span>
                             </div>
                        </div>
                    )}

                    {/* Input Box */}
                    <div className="relative flex items-center gap-2 bg-zinc-900/90 p-2 rounded-xl border border-zinc-700 shadow-2xl focus-within:border-indigo-500 focus-within:ring-1 focus-within:ring-indigo-500 transition-all backdrop-blur-md">

                        {/* Upload Button */}
                        <label className="p-3 text-zinc-400 hover:text-white cursor-pointer hover:bg-zinc-800 rounded-lg transition-colors" title="Upload Image for Editing">
                            <Upload className="w-5 h-5" />
                            <input type="file" className="hidden" accept="image/*" onChange={handleFileUpload} />
                        </label>

                        <textarea
                            value={params.prompt}
                            onChange={(e) => setParams(prev => ({ ...prev, prompt: e.target.value }))}
                            placeholder={params.uploadedImage ? "Describe how to edit this image..." : "Describe the image you want to create..."}
                            className="flex-1 bg-transparent border-none focus:ring-0 text-zinc-100 placeholder-zinc-500 resize-none h-12 py-3 leading-relaxed"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    handleGenerate();
                                }
                            }}
                        />

                        <button
                            onClick={() => handleGenerate()}
                            disabled={isGenerating}
                            className={`p-3 rounded-lg flex items-center gap-2 font-medium transition-all ${
                                isGenerating 
                                ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' 
                                : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-500/20 active:scale-95'
                            }`}
                        >
                            {isGenerating ? (
                                <Loader2 className="w-5 h-5 animate-spin" />
                            ) : (
                                <>
                                    <span className="hidden sm:inline">Generate</span>
                                    <Wand2 className="w-4 h-4" />
                                </>
                            )}
                        </button>
                    </div>

                    {error && (
                        <div className="text-red-400 text-sm bg-red-400/10 p-3 rounded-lg border border-red-400/20 animate-in fade-in slide-in-from-bottom-2">
                            Error: {error}
                        </div>
                    )}
                </div>
            </div>
        </div>

        {/* History Rail */}
        <HistoryStrip 
            images={history} 
            onSelect={(img) => setCurrentBatch([img])}
            onDelete={(id) => {
                setHistory(prev => prev.filter(i => i.id !== id));
                setCurrentBatch(prev => prev.filter(i => i.id !== id));
            }}
            onIterate={handleIterate}
            onUseAsReference={handleUseAsReference}
        />
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { GeneratedImage } from '../types';
import { Download, X, Maximize2, Grid2X2, Layers, Sparkles, ChevronLeft, ChevronRight } from 'lucide-react';

interface ImageViewerProps {
    images: GeneratedImage[];
    onClose: () => void;
    onUseAsReference: (image: GeneratedImage) => void;
    onIterate: (image: GeneratedImage) => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ images, onClose, onUseAsReference, onIterate }) => {
    const [focusedIndex, setFocusedIndex] = useState<number | null>(null);

    // Reset focus when the image set changes completely
    useEffect(() => {
        setFocusedIndex(null);
    }, [images]);

    const handleNext = useCallback(() => {
        setFocusedIndex(prev => {
            if (prev === null) return null;
            return prev < images.length - 1 ? prev + 1 : 0; // Wrap around
        });
    }, [images.length]);

    const handlePrev = useCallback(() => {
        setFocusedIndex(prev => {
            if (prev === null) return null;
            return prev > 0 ? prev - 1 : images.length - 1; // Wrap around
        });
    }, [images.length]);

    // Keyboard navigation
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (focusedIndex === null) return;

            if (e.key === 'ArrowRight') {
                handleNext();
            } else if (e.key === 'ArrowLeft') {
                handlePrev();
            } else if (e.key === 'Escape') {
                // If in single view and there are multiple images, go back to grid
                if (images.length > 1) {
                    setFocusedIndex(null);
                } else {
                    // Otherwise close viewer
                    onClose();
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [focusedIndex, handleNext, handlePrev, images.length, onClose]);


    if (!images || images.length === 0) return null;

    const handleDownload = (img: GeneratedImage) => {
        const link = document.createElement('a');
        link.href = img.url;
        link.download = `nano-studio-${img.timestamp}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleReferenceClick = (img: GeneratedImage) => {
        onUseAsReference(img);
        onClose(); // Close the viewer to go back to the prompt screen
    };

    // Determine viewing mode
    // If only 1 image exists, forces single view.
    // If multiple images exist, defaults to grid, unless focusedIndex is set.
    const isSingleView = images.length === 1 || focusedIndex !== null;
    const activeIndex = images.length === 1 ? 0 : (focusedIndex !== null ? focusedIndex : 0);
    const activeImage = images[activeIndex];

    // --- Single Image View ---
    if (isSingleView && activeImage) {
        return (
            <div className="flex-1 flex items-center justify-center bg-zinc-950/50 p-2 sm:p-4 md:p-6 overflow-hidden relative animate-in fade-in duration-200">
                <div className="relative w-full max-w-5xl max-h-full flex flex-col shadow-2xl shadow-black/50 rounded-2xl overflow-hidden bg-zinc-900 border border-zinc-800 group/container">

                    {/* Navigation Buttons (Only if multiple images) */}
                    {images.length > 1 && (
                        <>
                            <button 
                                onClick={handlePrev}
                                className="absolute left-4 top-1/2 -translate-y-1/2 z-20 p-2 bg-black/50 hover:bg-black/80 text-white rounded-full backdrop-blur-sm transition-all border border-white/10 opacity-0 group-hover/container:opacity-100 hover:scale-110"
                                title="Previous Image (Left Arrow)"
                            >
                                <ChevronLeft className="w-6 h-6" />
                            </button>
                            <button 
                                onClick={handleNext}
                                className="absolute right-4 top-1/2 -translate-y-1/2 z-20 p-2 bg-black/50 hover:bg-black/80 text-white rounded-full backdrop-blur-sm transition-all border border-white/10 opacity-0 group-hover/container:opacity-100 hover:scale-110"
                                title="Next Image (Right Arrow)"
                            >
                                <ChevronRight className="w-6 h-6" />
                            </button>
                        </>
                    )}

                    {/* Toolbar */}
                    <div className="absolute top-4 right-4 z-10 flex gap-2">
                        {images.length > 1 && (
                            <button 
                                onClick={() => setFocusedIndex(null)}
                                className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                                title="Back to Grid (Esc)"
                            >
                                <Grid2X2 className="w-5 h-5" />
                            </button>
                        )}
                         <button 
                            onClick={() => handleReferenceClick(activeImage)}
                            className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Use as Reference"
                        >
                            <Layers className="w-5 h-5" />
                        </button>
                         <button 
                            onClick={() => onIterate(activeImage)}
                            className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Iterate Variations"
                        >
                            <Sparkles className="w-5 h-5" />
                        </button>
                        <button 
                            onClick={() => handleDownload(activeImage)}
                            className="p-2 bg-black/50 hover:bg-black/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Download"
                        >
                            <Download className="w-5 h-5" />
                        </button>
                        <button 
                            onClick={onClose}
                            className="p-2 bg-black/50 hover:bg-red-500/80 text-white rounded-lg backdrop-blur-sm transition-all border border-white/10"
                            title="Close View"
                        >
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    {/* Image Container */}
                    <div className="flex-1 overflow-hidden flex items-center justify-center bg-zinc-950/50 p-1 select-none">
                        <img 
                            key={activeImage.id} // Key change triggers animation if we want, but usually standard replacement is smoother
                            src={activeImage.url} 
                            alt={activeImage.prompt} 
                            className="max-w-full max-h-full object-contain shadow-lg animate-in fade-in duration-300"
                        />
                    </div>

                    {/* Info Footer */}
                    <div className="bg-zinc-900 p-4 border-t border-zinc-800 shrink-0">
                        <div className="flex items-center justify-between mb-1">
                            <p className="text-zinc-100 font-medium truncate">{activeImage.prompt}</p>
                            {images.length > 1 && (
                                <span className="text-xs text-zinc-500 font-mono ml-4 shrink-0">
                                    {activeIndex + 1} / {images.length}
                                </span>
                            )}
                        </div>
                        <div className="flex flex-wrap gap-4 text-xs text-zinc-500 font-mono">
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Seed:</span> 
                                <span className="text-zinc-300">{activeImage.params.seed}</span>
                             </div>
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Styles:</span>
                                <span className="text-zinc-300">{activeImage.params.styleA} + {activeImage.params.styleB}</span>
                             </div>
                             <div className="flex items-center gap-1">
                                <span className="text-zinc-600">Point:</span>
                                <span className="text-indigo-400">[{activeImage.usedPoint.x}, {activeImage.usedPoint.y}]</span>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    // --- Grid View ---
    return (
        <div className="flex-1 flex flex-col p-4 md:p-6 overflow-hidden relative animate-in fade-in duration-300">
             <div className="absolute top-4 right-4 md:right-6 z-10">
                <button 
                    onClick={onClose}
                    className="p-2 bg-zinc-900/80 hover:bg-red-500/80 text-white rounded-lg backdrop-blur-sm transition-all border border-zinc-700 hover:border-red-500 shadow-lg"
                    title="Close Gallery"
                >
                    <X className="w-5 h-5" />
                </button>
            </div>

            <div className="flex-1 overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-zinc-700 scrollbar-track-transparent">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 max-w-6xl mx-auto h-full content-start py-8">
                    {images.map((img, idx) => (
                        <div 
                            key={img.id} 
                            className="group relative aspect-square bg-zinc-900 rounded-2xl overflow-hidden border border-zinc-800 hover:border-indigo-500/50 transition-all shadow-xl hover:shadow-2xl hover:shadow-indigo-500/10"
                        >
                            <img src={img.url} alt={img.prompt} className="w-full h-full object-cover" />

                            {/* Hover Overlay */}
                            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 flex flex-col justify-end p-5">
                                <div className="flex justify-end gap-2 mb-auto pt-2 translate-y-4 group-hover:translate-y-0 transition-transform duration-300">
                                     <button 
                                        onClick={() => setFocusedIndex(idx)}
                                        className="p-2.5 bg-black/60 hover:bg-indigo-600 text-white rounded-xl backdrop-blur-md transition-all border border-white/10"
                                        title="Maximize"
                                    >
                                        <Maximize2 className="w-5 h-5" />
                                    </button>
                                     <button 
                                        onClick={() => handleReferenceClick(img)}
                                        className="p-2.5 bg-black/60 hover:bg-blue-600 text-white rounded-xl backdrop-blur-md transition-all border border-white/10"
                                        title="Use as Reference"
                                    >
                                        <Layers className="w-5 h-5" />
                                    </button>
                                     <button 
                                        onClick={() => onIterate(img)}
                                        className="p-2.5 bg-black/60 hover:bg-amber-500 text-white rounded-xl backdrop-blur-md transition-all border border-white/10"
                                        title="Iterate Variations"
                                    >
                                        <Sparkles className="w-5 h-5" />
                                    </button>
                                     <button 
                                        onClick={() => handleDownload(img)}
                                        className="p-2.5 bg-black/60 hover:bg-emerald-600 text-white rounded-xl backdrop-blur-md transition-all border border-white/10"
                                        title="Download"
                                    >
                                        <Download className="w-5 h-5" />
                                    </button>
                                </div>
                                <div className="transform translate-y-2 group-hover:translate-y-0 transition-transform duration-300">
                                    <div className="flex items-center gap-2 mb-2">
                                        <span className="px-2 py-0.5 rounded-md bg-white/10 text-[10px] text-zinc-300 font-mono border border-white/5">
                                            {img.params.styleA}
                                        </span>
                                        <span className="px-2 py-0.5 rounded-md bg-white/10 text-[10px] text-zinc-300 font-mono border border-white/5">
                                            {img.params.styleB}
                                        </span>
                                    </div>
                                    <div className="text-sm font-medium text-white line-clamp-1 opacity-90">{img.prompt}</div>
                                </div>
                            </div>

                            {/* Always visible coordinate badge */}
                            <div className="absolute top-3 left-3 px-2 py-1 rounded bg-black/40 backdrop-blur-sm border border-white/10 text-[10px] text-zinc-400 font-mono opacity-60 group-hover:opacity-0 transition-opacity">
                                [{img.usedPoint.x}, {img.usedPoint.y}]
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

