import { Wand2, Loader2, Upload, X, Image as ImageIcon, Menu } from 'lucide-react';

const INITIAL_ANGLE = Math.floor(Math.random() * 360);
// Helper to match the seed dial's logic for initial consistency
const getInitialSeed = (angle: number) => {
    const chaos = Math.sin(angle * 12.9898) * 43758.5453;
    return Math.floor(Math.abs(chaos) * 1000000);
}

const DEFAULT_PARAMS: GenerationParams = {
  prompt: "",
  imageCount: 1,
  seed: getInitialSeed(INITIAL_ANGLE),
  seedAngle: INITIAL_ANGLE,
  styleA: StyleOption.CYBERPUNK,
  styleB: StyleOption.REALISTIC,
  matrixPoints: [{ x: 0.5, y: 0.5 }], // Default to single point
  negativePrompts: [],
  uploadedImage: undefined,
  model: ModelOption.FLASH,
  colorPalette: ColorPalette.NONE,
  aspectRatio: AspectRatio.SQUARE,
  lighting: Lighting.NONE,
  depthOfField: DepthOfField.NONE
};

const App: React.FC = () => {
  const [params, setParams] = useState<GenerationParams>(DEFAULT_PARAMS);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [currentBatch, setCurrentBatch] = useState<GeneratedImage[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const handleGenerate = async (overrideParams?: Partial<GenerationParams>) => {
    const currentParams = { ...params, ...overrideParams };

    if (!currentParams.prompt.trim() && !currentParams.uploadedImage) {
        setError("Please enter a prompt or upload an image.");
        return;
    }

    setIsGenerating(true);
    setError(null);
    if (isSidebarOpen) setIsSidebarOpen(false);

    // Seed is now strictly controlled by the Dial. 
    // We do not re-randomize here automatically unless explicit buttons were clicked (handled in Sidebar).
    const generationParams = { ...currentParams };

    // Update the main params state if we're doing a manual generation
    if (!overrideParams) {
        setParams(generationParams);
    }

    try {
      const results = await generateImages(generationParams);

      if (results.length === 0) {
        throw new Error("No images generated. Please try again.");
      }

      const newImages: GeneratedImage[] = results.map(res => ({
        id: crypto.randomUUID(),
        url: res.url,
        prompt: generationParams.prompt || "Image Edit",
        timestamp: Date.now(),
        params: generationParams,
        usedPoint: res.point
      }));

      setHistory(prev => [...newImages, ...prev]);
      setCurrentBatch(newImages); 
    } catch (err: any) {
      setError(err.message || "Failed to generate image.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleIterate = (image: GeneratedImage) => {
      // For iteration, we want to start from the image's params, but slight variation?
      // Actually, if we just use the same seed, we get the same image.
      // To "Iterate", we should probably spin the dial slightly or randomize it.
      // Let's randomize it to provide a new variation of the same prompt/settings.
      const randomAngle = Math.floor(Math.random() * 360);
      const chaos = Math.sin(randomAngle * 12.9898) * 43758.5453;
      const newSeed = Math.floor(Math.abs(chaos) * 1000000);

      const iterationParams = { 
          ...image.params, 
          seed: newSeed,
          seedAngle: randomAngle
      };
      setParams(iterationParams); // Update sidebar UI to reflect the change
      handleGenerate(iterationParams);
  };

  const handleUseAsReference = (image: GeneratedImage) => {
      // Restore all parameters from the selected image and set its URL as the uploaded image
      setParams({ ...image.params, uploadedImage: image.url });
      // Clear the current view to return to the prompt input
      setCurrentBatch([]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setParams(prev => ({ ...prev, uploadedImage: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const clearUpload = () => {
      setParams(prev => ({ ...prev, uploadedImage: undefined }));
  };

  return (
    <div className="flex h-screen w-screen bg-zinc-950 text-zinc-100 overflow-hidden">

      {/* Backdrop for mobile sidebar */}
      {isSidebarOpen && (
        <div 
            className="fixed inset-0 bg-black/60 z-40 md:hidden"
            onClick={() => setIsSidebarOpen(false)}
            aria-hidden="true"
        />
      )}

      {/* Sidebar */}
      <Sidebar 
        params={params} 
        setParams={setParams} 
        isGenerating={isGenerating}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Top Bar / Header */}
        <div className="h-16 border-b border-zinc-800 flex items-center px-4 md:px-6 justify-between bg-zinc-900/50 backdrop-blur-sm shrink-0">
            <div className="flex items-center gap-2 md:gap-3">
                 <button 
                    onClick={() => setIsSidebarOpen(true)}
                    className="md:hidden p-2 -ml-2 text-zinc-400 hover:text-white"
