import React, { useState, useRef, useEffect, useCallback } from 'react';
import { RefreshCw } from 'lucide-react';

interface SeedDialProps {
    angle: number;
    seed: number;
    onChange: (angle: number, seed: number) => void;
}

// A chaotic but deterministic function to map angle to a large seed
const getSeedFromAngle = (angle: number): number => {
    // We use a sine wave with high frequency to ensure that 
    // moving from degree 1 to 2 produces a vastly different number.
    // We add a large offset to keep it looking like a "seed".
    const chaos = Math.sin(angle * 12.9898) * 43758.5453;
    const largeInt = Math.floor(Math.abs(chaos) * 1000000);
    return largeInt;
};

export const SeedDial: React.FC<SeedDialProps> = ({ angle, seed, onChange }) => {
    const dialRef = useRef<HTMLDivElement>(null);
    const [isDragging, setIsDragging] = useState(false);

    const handleRandomize = () => {
        const randomAngle = Math.floor(Math.random() * 360);
        const newSeed = getSeedFromAngle(randomAngle);
        onChange(randomAngle, newSeed);
    };

    const calculateAngle = useCallback((clientX: number, clientY: number) => {
        if (!dialRef.current) return;
        const rect = dialRef.current.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const centerY = rect.top + rect.height / 2;

        // Calculate angle in radians
        const radians = Math.atan2(clientY - centerY, clientX - centerX);

        // Convert to degrees and normalize to 0-360, shifting so 0 is at top (standard knob)
        let degrees = radians * (180 / Math.PI);
        degrees = (degrees + 90 + 360) % 360;

        return Math.floor(degrees);
    }, []);

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!isDragging) return;
            const newAngle = calculateAngle(e.clientX, e.clientY);
            if (newAngle !== undefined) {
                const newSeed = getSeedFromAngle(newAngle);
                onChange(newAngle, newSeed);
            }
        };

        const handleMouseUp = () => {
            setIsDragging(false);
            document.body.style.cursor = 'default';
        };

        if (isDragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
            document.body.style.cursor = 'grabbing';
        }

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, calculateAngle, onChange]);

    const handleMouseDown = (e: React.MouseEvent) => {
        e.preventDefault();
        setIsDragging(true);
        // Instant update on click
        const newAngle = calculateAngle(e.clientX, e.clientY);
         if (newAngle !== undefined) {
            const newSeed = getSeedFromAngle(newAngle);
            onChange(newAngle, newSeed);
        }
    };

    // Visual styles based on angle
    // We shift the color of the glow based on the angle to reinforce the "variety" aspect
    const glowColor = `hsl(${angle}, 70%, 50%)`;

    return (
        <div className="flex items-center gap-4">
            {/* The Knob */}
            <div 
                className="relative w-20 h-20 shrink-0"
                onMouseDown={handleMouseDown}
                ref={dialRef}
            >
                {/* Tick Marks Ring */}
                <div className="absolute inset-0 rounded-full border border-zinc-700 bg-zinc-800/50" />
                {[...Array(12)].map((_, i) => (
                    <div 
                        key={i}
                        className="absolute w-0.5 h-1.5 bg-zinc-600 origin-bottom"
                        style={{
                            top: '4px',
                            left: '50%',
                            transform: `translateX(-50%) rotate(${i * 30}deg)`,
                            transformOrigin: '50% 36px' // Radius of the ring approx
                        }}
                    />
                ))}

                {/* Rotatable Body */}
                <div 
                    className="absolute inset-2 bg-gradient-to-br from-zinc-700 to-zinc-900 rounded-full shadow-xl border border-zinc-600 cursor-grab active:cursor-grabbing flex items-center justify-center"
                    style={{ 
                        transform: `rotate(${angle}deg)`,
                        boxShadow: isDragging ? `0 0 15px ${glowColor}40` : ''
                        }}
                >
                        {/* Indicator Dot */}
                        <div className="absolute top-1.5 w-1.5 h-1.5 rounded-full" 
                            style={{ 
                                backgroundColor: glowColor,
                                boxShadow: `0 0 8px ${glowColor}`
                            }} 
                    />
                        {/* Inner div for visual complexity */}
                        <div className="w-8 h-8 rounded-full bg-zinc-800 border border-zinc-700/50 shadow-inner" />
                </div>
            </div>

            {/* Instructions / Randomize */}
            <div className="flex flex-col justify-center gap-2 flex-1">
                <p className="text-[10px] text-zinc-500 leading-tight">
                    Rotate to explore the randomness spectrum. Every tick is a new universe.
                </p>
                <button 
                    onClick={handleRandomize}
                    className="flex items-center justify-center gap-2 py-2 px-3 bg-zinc-800 hover:bg-zinc-700 text-xs text-zinc-300 rounded-lg transition-colors border border-zinc-700"
                >
                    <RefreshCw className="w-3 h-3" />
                    Spin Dial
                </button>
            </div>
        </div>
    );
};

import React from 'react';
import { GenerationParams, StyleOption, NEGATIVE_PROMPTS_OPTIONS, Point, ModelOption, ColorPalette, AspectRatio, Lighting, DepthOfField } from '../types';
import { Settings2, MinusCircle, Sliders, LayoutGrid, Square, Diamond, MousePointer2, Move, Palette, Cpu, X, BoxSelect, Sun, Aperture, Zap, RefreshCw } from 'lucide-react';
import { MatrixPlotter } from './MatrixPlotter';
import { SeedDial } from './SeedDial';

interface SidebarProps {
  params: GenerationParams;
  setParams: React.Dispatch<React.SetStateAction<GenerationParams>>;
  isGenerating: boolean;
  isOpen: boolean;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ params, setParams, isGenerating, isOpen, onClose }) => {

  const handleStyleChange = (key: 'styleA' | 'styleB', value: string) => {
    setParams(prev => ({ ...prev, [key]: value }));
  };

  const toggleNegativePrompt = (option: string) => {
    setParams(prev => {
      const current = prev.negativePrompts;
      if (current.includes(option)) {
        return { ...prev, negativePrompts: current.filter(o => o !== option) };
      } else {
        return { ...prev, negativePrompts: [...current, option] };
      }
    });
  };

  const setMatrixPattern = (type: 'single' | 'corners' | 'diamond' | 'grid' | 'free4') => {
      let newPoints: Point[] = [];
      switch (type) {
          case 'single':
              newPoints = [{ x: 0, y: 0 }];
              break;
          case 'corners':
              newPoints = [
                  { x: -0.9, y: 0.9 }, // Top Left
                  { x: 0.9, y: 0.9 },  // Top Right
                  { x: -0.9, y: -0.9 },// Bottom Left
                  { x: 0.9, y: -0.9 }  // Bottom Right
              ];
              break;
          case 'diamond':
              newPoints = [
                  { x: 0, y: 0.9 },  // Top
                  { x: 0.9, y: 0 },  // Right
                  { x: 0, y: -0.9 }, // Bottom
                  { x: -0.9, y: 0 }  // Left
              ];
              break;
          case 'grid':
              // Cross pattern
              newPoints = [
                { x: 0, y: 0 },
                { x: 0.8, y: 0.8 },
                { x: -0.8, y: 0.8 },
                { x: 0.8, y: -0.8 },
                { x: -0.8, y: -0.8 }
              ];
              break;
          case 'free4':
              // 4 Centered points for manual placement
              newPoints = [
                  { x: -0.5, y: 0.5 },
                  { x: 0.5, y: 0.5 },
                  { x: -0.5, y: -0.5 },
                  { x: 0.5, y: -0.5 }
              ];
              break;
      }
      setParams(prev => ({ ...prev, matrixPoints: newPoints }));
  };

  const isMultiPoint = params.matrixPoints.length > 1;

  return (
    <div className={`
        fixed inset-y-0 left-0 z-50 bg-zinc-900 border-r border-zinc-800 flex flex-col overflow-y-auto p-4
        w-full max-w-sm transform transition-transform duration-300 ease-in-out
        md:static md:w-80 md:shrink-0 md:translate-x-0
        ${isOpen ? 'translate-x-0' : '-translate-x-full'}
    `}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center">
                <Settings2 className="w-5 h-5 text-white" />
            </div>
            <h2 className="text-lg font-bold text-zinc-100">Configuration</h2>
        </div>
        <button onClick={onClose} className="md:hidden p-1 text-zinc-500 hover:text-white" aria-label="Close settings">
            <X className="w-6 h-6" />
        </button>
      </div>

      {/* Generation Settings */}
      <div className="space-y-6">

        {/* Model Selection */}
        <div className="space-y-2">
            <div className="flex items-center gap-2 text-sm font-medium text-zinc-300">
                <Cpu className="w-4 h-4 text-blue-400" />
                AI Model
            </div>
            <select
                value={params.model}
                onChange={(e) => setParams(prev => ({ ...prev, model: e.target.value as ModelOption }))}
                className="w-full bg-zinc-800 text-sm text-zinc-200 p-2.5 rounded-lg border border-zinc-700 focus:border-indigo-500 outline-none"
                disabled={isGenerating}
            >
                <option value={ModelOption.FLASH}>Gemini 2.5 Flash (Fast)</option>
                <option value={ModelOption.PRO}>Gemini 3 Pro (High Quality)</option>
            </select>
        </div>

        {/* Dimension & Light Group */}
        <div className="grid grid-cols-2 gap-3">
             {/* Aspect Ratio */}
            <div className="space-y-2">
                <div className="flex items-center gap-2 text-sm font-medium text-zinc-300">
                    <BoxSelect className="w-4 h-4 text-orange-400" />
                    Ratio
                </div>
                <select
                    value={params.aspectRatio}
                    onChange={(e) => setParams(prev => ({ ...prev, aspectRatio: e.target.value as AspectRatio }))}
                    className="w-full bg-zinc-800 text-sm text-zinc-200 p-2.5 rounded-lg border border-zinc-700 focus:border-indigo-500 outline-none"
                    disabled={isGenerating}
                >
                    <option value={AspectRatio.SQUARE}>1:1 Square</option>
                    <option value={AspectRatio.LANDSCAPE}>16:9 Landscape</option>
                    <option value={AspectRatio.PORTRAIT}>9:16 Portrait</option>
                    <option value={AspectRatio.CLASSIC}>4:3 Classic</option>
                    <option value={AspectRatio.WIDE}>3:4 Tall</option>
                </select>
            </div>

            {/* Color Palette */}
            <div className="space-y-2">
                <div className="flex items-center gap-2 text-sm font-medium text-zinc-300">
                    <Palette className="w-4 h-4 text-pink-400" />
                    Palette
                </div>
                <select
                    value={params.colorPalette}
                    onChange={(e) => setParams(prev => ({ ...prev, colorPalette: e.target.value as ColorPalette }))}
                    className="w-full bg-zinc-800 text-sm text-zinc-200 p-2.5 rounded-lg border border-zinc-700 focus:border-indigo-500 outline-none"
                    disabled={isGenerating}
                >
                    <option value={ColorPalette.NONE}>Default</option>
                    {Object.values(ColorPalette).filter(v => v !== ColorPalette.NONE).map(palette => (
                        <option key={palette} value={palette}>{palette}</option>
                    ))}
                </select>
            </div>
        </div>

        {/* Lighting & Depth */}
        <div className="space-y-2 pt-2 border-t border-zinc-800">
             <div className="flex items-center gap-2 text-sm font-medium text-zinc-300 mb-2">
                <Sun className="w-4 h-4 text-yellow-400" />
                Lighting & Atmosphere
            </div>
            <select
                value={params.lighting}
                onChange={(e) => setParams(prev => ({ ...prev, lighting: e.target.value as Lighting }))}
                className="w-full bg-zinc-800 text-sm text-zinc-200 p-2.5 rounded-lg border border-zinc-700 focus:border-indigo-500 outline-none mb-3"
                disabled={isGenerating}
            >
                <option value={Lighting.NONE}>Default Lighting</option>
                {Object.values(Lighting).filter(v => v !== Lighting.NONE).map(l => (
                    <option key={l} value={l}>{l}</option>
                ))}
            </select>

            <div className="flex items-center gap-2 text-sm font-medium text-zinc-300 mb-2">
                <Aperture className="w-4 h-4 text-emerald-400" />
