const constructEnrichedPrompt = (params: GenerationParams, point: Point): string => {
  const { prompt, styleA, styleB, negativePrompts, colorPalette, lighting, depthOfField } = params;
  const { x: matrixX, y: matrixY } = point;

  let enrichedPrompt = `Subject: ${prompt}.`;

  // Apply Modifiers
  if (lighting && LIGHTING_PROMPTS[lighting]) {
    enrichedPrompt += ` Lighting: ${LIGHTING_PROMPTS[lighting]}.`;
  }

  if (depthOfField && DEPTH_PROMPTS[depthOfField]) {
    enrichedPrompt += ` Focus: ${DEPTH_PROMPTS[depthOfField]}.`;
  }

  if (colorPalette && COLOR_PALETTE_PROMPTS[colorPalette]) {
    enrichedPrompt += ` Color Scheme: ${COLOR_PALETTE_PROMPTS[colorPalette]}.`;
  }

  const getStyleInstruction = (style: string, intensity: number): string => {
    if (style === StyleOption.NONE || !STYLE_PROMPTS[style]) return "";

    // Ignore small values close to center to prevent noise
    if (Math.abs(intensity) < 0.15) return "";

    const keywords = STYLE_PROMPTS[style];

    if (intensity > 0) {
        // Positive Influence
        if (intensity > 0.6) {
            return `Strongly apply style: ${style}. key visuals: ${keywords}. (Weight: High)`;
        } else {
             return `Blend with style: ${style}. key visuals: ${keywords}. (Weight: Medium)`;
        }
    } else {
        // Negative Influence (Avoidance)
        return `Strictly avoid ${style} style. Ensure image does NOT contain: ${keywords}.`;
    }
  };

  const instructionA = getStyleInstruction(styleA, matrixX);
  const instructionB = getStyleInstruction(styleB, matrixY);

  if (instructionA) enrichedPrompt += ` ${instructionA}`;
  if (instructionB) enrichedPrompt += ` ${instructionB}`;

  // Negative Prompts
  if (negativePrompts.length > 0) {
    enrichedPrompt += ` Negative constraints (avoid): ${negativePrompts.join(", ")}.`;
  }

  // Quality Boosters
  enrichedPrompt += " Image requirements: High fidelity, detailed texture, accurate lighting, aesthetically pleasing composition.";

  return enrichedPrompt;
};

interface GenerationResult {
    url: string;
    point: Point;
}

export const generateImages = async (params: GenerationParams): Promise<GenerationResult[]> => {
  // SECURITY CHECK: Ensure API Key is present
  if (!process.env.API_KEY) {
    throw new Error("Missing API Key. Please configure the API_KEY environment variable.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const tasks: { point: Point; seed: number | undefined }[] = [];

  if (params.matrixPoints.length > 1) {
    params.matrixPoints.forEach((point, index) => {
        tasks.push({
            point,
            seed: params.seed + index // Deterministic batch
        });
    });
  } else {
    const point = params.matrixPoints[0] || { x: 0, y: 0 };
    for (let i = 0; i < params.imageCount; i++) {
        tasks.push({
            point,
            seed: params.seed + i // Deterministic batch
        });
    }
  }

  const promises = tasks.map(async (task) => {
    const finalPrompt = constructEnrichedPrompt(params, task.point);
    const config: any = { 
        seed: task.seed,
        imageConfig: {
            aspectRatio: params.aspectRatio
        }
    };

    if (params.model === ModelOption.PRO) {
        config.imageConfig.imageSize = "1K";
    }

    try {
      const parts: any[] = [{ text: finalPrompt }];

      if (params.uploadedImage) {
        parts.unshift({
          inlineData: {
            data: extractBase64Data(params.uploadedImage),
            mimeType: getMimeType(params.uploadedImage),
          }
        });
      }

      const response = await ai.models.generateContent({
        model: params.model,
        contents: { parts },
        config
      });

      if (response?.candidates?.[0]?.content?.parts) {
         for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
               return {
                 url: `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`,
                 point: task.point
               };
            }
         }
      }
      throw new Error("Model returned no image data.");
    } catch (error: any) {
      // Propagate error message to UI
      throw new Error(error.message || "Failed to generate image.");
    }
  });

  // Use allSettled to allow partial success in a batch
  const results = await Promise.allSettled(promises);

  const successfulImages: GenerationResult[] = [];
  let errorMsg = "";

  results.forEach(result => {
      if (result.status === 'fulfilled') {
          successfulImages.push(result.value);
      } else {
          errorMsg = result.reason.message;
      }
  });

  if (successfulImages.length === 0 && errorMsg) {
      throw new Error(errorMsg);
  }

  return successfulImages;
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { RefreshCw } from 'lucide-react';

interface SeedDialProps {
    angle: number;
    seed: number;
    onChange: (angle: number, seed: number) => void;
}

const getSeedFromAngle = (angle: number): number => {
    const chaos = Math.sin(angle * 12.9898) * 43758.5453;
    const largeInt = Math.floor(Math.abs(chaos) * 1000000);
    return largeInt;
};

export const SeedDial: React.FC<SeedDialProps> = ({ angle, seed, onChange }) => {
    const dialRef = useRef<HTMLDivElement>(null);
    const [isDragging, setIsDragging] = useState(false);

    const handleRandomize = () => {
        const randomAngle = Math.floor(Math.random() * 360);
        const newSeed = getSeedFromAngle(randomAngle);
        onChange(randomAngle, newSeed);
    };

    const calculateAngle = useCallback((clientX: number, clientY: number) => {
        if (!dialRef.current) return;
        const rect = dialRef.current.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const centerY = rect.top + rect.height / 2;

        const radians = Math.atan2(clientY - centerY, clientX - centerX);
        let degrees = radians * (180 / Math.PI);
        degrees = (degrees + 90 + 360) % 360;

        return Math.floor(degrees);
    }, []);

    // Unified Input Handler for Mouse and Touch
    const handleMove = useCallback((clientX: number, clientY: number) => {
        const newAngle = calculateAngle(clientX, clientY);
        if (newAngle !== undefined) {
            const newSeed = getSeedFromAngle(newAngle);
            onChange(newAngle, newSeed);
        }
    }, [calculateAngle, onChange]);

    // Mouse Events
    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!isDragging) return;
            handleMove(e.clientX, e.clientY);
        };
        const handleMouseUp = () => {
            setIsDragging(false);
            document.body.style.cursor = 'default';
        };

        if (isDragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
            document.body.style.cursor = 'grabbing';
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, handleMove]);

    // Touch Events (Passive listener issue on some browsers handled by React usually, but manual binding safer for move)
    useEffect(() => {
        const handleTouchMove = (e: TouchEvent) => {
            if (!isDragging) return;
            e.preventDefault(); // Prevent scrolling while rotating
            const touch = e.touches[0];
            handleMove(touch.clientX, touch.clientY);
        };
        const handleTouchEnd = () => setIsDragging(false);

        if (isDragging) {
            window.addEventListener('touchmove', handleTouchMove, { passive: false });
            window.addEventListener('touchend', handleTouchEnd);
        }
        return () => {
            window.removeEventListener('touchmove', handleTouchMove);
            window.removeEventListener('touchend', handleTouchEnd);
        };
    }, [isDragging, handleMove]);

    const handleStart = (e: React.MouseEvent | React.TouchEvent) => {
        // Stop propagation to prevent Sidebar from grabbing scroll
        e.stopPropagation(); 
        setIsDragging(true);

        let clientX, clientY;
        if ('touches' in e) {
            clientX = e.touches[0].clientX;
            clientY = e.touches[0].clientY;
        } else {
            e.preventDefault();
            clientX = (e as React.MouseEvent).clientX;
            clientY = (e as React.MouseEvent).clientY;
        }

        handleMove(clientX, clientY);
    };

    const glowColor = `hsl(${angle}, 70%, 50%)`;

    return (
        <div className="flex items-center gap-4">
            <div 
                className="relative w-20 h-20 shrink-0 touch-none"
                onMouseDown={handleStart}
                onTouchStart={handleStart}
                ref={dialRef}
            >
                {/* Tick Marks */}
                <div className="absolute inset-0 rounded-full border border-zinc-700 bg-zinc-800/50" />
                {[...Array(12)].map((_, i) => (
                    <div 
                        key={i}
                        className="absolute w-0.5 h-1.5 bg-zinc-600 origin-bottom"
                        style={{
                            top: '4px',
                            left: '50%',
                            transform: `translateX(-50%) rotate(${i * 30}deg)`,
                            transformOrigin: '50% 36px'
                        }}
                    />
                ))}

                {/* Rotatable Body */}
                <div 
                    className="absolute inset-2 bg-gradient-to-br from-zinc-700 to-zinc-900 rounded-full shadow-xl border border-zinc-600 flex items-center justify-center transition-shadow duration-75"
                    style={{ 
                        transform: `rotate(${angle}deg)`,
                        boxShadow: isDragging ? `0 0 15px ${glowColor}40` : ''
                    }}
                >
                        <div className="absolute top-1.5 w-1.5 h-1.5 rounded-full" 
                            style={{ 
                                backgroundColor: glowColor,
                                boxShadow: `0 0 8px ${glowColor}`
                            }} 
                    />
                        <div className="w-8 h-8 rounded-full bg-zinc-800 border border-zinc-700/50 shadow-inner" />
                </div>
            </div>

            <div className="flex flex-col justify-center gap-2 flex-1">
                <p className="text-[10px] text-zinc-500 leading-tight">
                    Rotate to explore the randomness spectrum.
                </p>
                <button 
                    onClick={handleRandomize}
                    className="flex items-center justify-center gap-2 py-3 px-3 bg-zinc-800 hover:bg-zinc-700 text-xs text-zinc-300 rounded-lg transition-colors border border-zinc-700 min-h-[44px]"
                >
                    <RefreshCw className="w-4 h-4" />
                    Spin Dial
                </button>
            </div>
        </div>
    );
};

import React, { useRef, useEffect, useState } from 'react';
import { Point } from '../types';

interface MatrixPlotterProps {
    points: Point[];
    onChange: (points: Point[]) => void;
    labelX: string;
    labelY: string;
}

export const MatrixPlotter: React.FC<MatrixPlotterProps> = ({ points, onChange, labelX, labelY }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [draggingIndex, setDraggingIndex] = useState<number | null>(null);

    const getCoordsFromEvent = (clientX: number, clientY: number): Point | null => {
        if (!containerRef.current) return null;
        const rect = containerRef.current.getBoundingClientRect();

        let newX = (clientX - rect.left) / rect.width;
        let newY = (clientY - rect.top) / rect.height;

        newX = Math.max(0, Math.min(1, newX));
        newY = Math.max(0, Math.min(1, newY));

        const coordX = parseFloat(((newX * 2) - 1).toFixed(2));
        const coordY = parseFloat((-((newY * 2) - 1)).toFixed(2));
        return { x: coordX, y: coordY };
    };

    const handleStart = (e: React.MouseEvent | React.TouchEvent, index: number) => {
        e.preventDefault();
        e.stopPropagation();
        setDraggingIndex(index);
    };

    const handleMove = (clientX: number, clientY: number) => {
        if (draggingIndex === null) return;

        const coords = getCoordsFromEvent(clientX, clientY);
        if (!coords) return;

        const newPoints = [...points];
        newPoints[draggingIndex] = coords;
        onChange(newPoints);
    };

    // Mouse Events
    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (draggingIndex !== null) handleMove(e.clientX, e.clientY);
        };
        const handleMouseUp = () => setDraggingIndex(null);

        if (draggingIndex !== null) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [draggingIndex, points]);

    // Touch Events
    useEffect(() => {
        const handleTouchMove = (e: TouchEvent) => {
            if (draggingIndex !== null) {
                e.preventDefault(); // Stop scrolling
                handleMove(e.touches[0].clientX, e.touches[0].clientY);
            }
        };
        const handleTouchEnd = () => setDraggingIndex(null);

        if (draggingIndex !== null) {
            window.addEventListener('touchmove', handleTouchMove, { passive: false });
            window.addEventListener('touchend', handleTouchEnd);
        }
        return () => {
            window.removeEventListener('touchmove', handleTouchMove);
            window.removeEventListener('touchend', handleTouchEnd);
        };
    }, [draggingIndex, points]);

    return (
        <div 
            ref={containerRef}
            className={`relative w-full aspect-square bg-zinc-900 rounded-lg border border-zinc-700 overflow-hidden select-none touch-none group ${
                draggingIndex !== null ? 'cursor-grabbing' : ''
            }`}
        >
            {/* Grid Lines */}
            <div className="absolute inset-0 pointer-events-none">
                <div className="absolute top-1/2 left-0 right-0 h-px bg-zinc-700" />
                <div className="absolute left-1/2 top-0 bottom-0 w-px bg-zinc-700" />
            </div>

            {/* Labels */}
            <div className="absolute top-2 right-2 text-[10px] text-green-500 font-mono pointer-events-none opacity-50">
                (+, +)
            </div>
            <div className="absolute bottom-2 left-2 text-[10px] text-red-500 font-mono pointer-events-none opacity-50">
                (-, -)
            </div>

            {/* Render All Points */}
            {points.map((p, idx) => {
                const percentX = ((p.x + 1) / 2) * 100;
                const percentY = ((-p.y + 1) / 2) * 100;
                const isMulti = points.length > 1;
                const isDraggingThis = idx === draggingIndex;

                return (
                    <div 
                        key={idx}
                        onMouseDown={(e) => handleStart(e, idx)}
                        onTouchStart={(e) => handleStart(e, idx)}
                        className={`absolute rounded-full transform -translate-x-1/2 -translate-y-1/2 transition-all duration-150 cursor-grab active:cursor-grabbing
                            ${isDraggingThis ? 'w-5 h-5 z-20' : 'w-4 h-4 z-10'}
                            ${isMulti ? 'bg-indigo-400 border border-white/80' : 'bg-indigo-500 border-2 border-white'}
                            ${isDraggingThis ? 'shadow-[0_0_15px_rgba(99,102,241,0.8)] scale-110' : 'shadow-lg shadow-indigo-500/30'}
                        `}
                        style={{ left: `${percentX}%`, top: `${percentY}%` }}
                    />
                );
            })}

            {/* Live readout */}
            <div className="absolute bottom-0 right-0 bg-zinc-900/90 px-2 py-1 text-[10px] text-zinc-400 font-mono border-tl rounded-tl backdrop-blur-sm pointer-events-none">
                {draggingIndex !== null 
                    ? `Active: X:${points[draggingIndex].x.toFixed(2)} Y:${points[draggingIndex].y.toFixed(2)}` 
                    : points.length > 1 ? `${points.length} Points` : `X:${points[0]?.x.toFixed(2)} Y:${points[0]?.y.toFixed(2)}`
                }
            </div>
        </div>
    );
};

