                <div className="space-y-1">
                    <label className="text-xs text-zinc-500 uppercase font-bold">Axis Y (Style B)</label>
                    <select 
                        value={params.styleB}
                        onChange={(e) => handleStyleChange('styleB', e.target.value)}
