                                View Billing Documentation
                            </a>
                        </p>
                    </div>
                </div>
            </div>
      );
  }

  return (
    <div className="flex h-[100dvh] w-full bg-zinc-950 text-zinc-100 overflow-hidden">

      {/* Mobile Backdrop */}
      {isSidebarOpen && (
        <div 
