}

// 2. Bridge Vite env vars to process.env.API_KEY
// CRITICAL: We must access import.meta.env.VITE_API_KEY directly 
// so the bundler performs static string replacement.
try {
  // @ts-ignore
  const viteKey = import.meta.env.VITE_API_KEY;
  // @ts-ignore
