const constructEnrichedPrompt = (params: GenerationParams, point: Point): string => {
  const { prompt, styleA, styleB, negativePrompts, colorPalette, lighting, depthOfField } = params;
  const { x: matrixX, y: matrixY } = point;

  // Structured Prompt Construction
  const sections: string[] = [];

  // 1. CORE SUBJECT
  sections.push(`[SUBJECT]\n${prompt}`);

  // 2. STYLE MATRIX & MIXING (High Precision)
  const styleDirectives: string[] = [];
  const negativeStyleDirectives: string[] = [];

  const processStyleAxis = (styleName: string, intensity: number) => {
      if (styleName === StyleOption.NONE || !STYLE_PROMPTS[styleName]) return;

      const keywords = STYLE_PROMPTS[styleName];
      // Micro-deadzone to avoid floating point noise at strict 0, but allow 1% granularity
      if (Math.abs(intensity) < 0.01) return;

      const percentage = (Math.abs(intensity) * 100).toFixed(0);

      if (intensity > 0) {
          // Positive application with granular weight
          styleDirectives.push(`   - Style: "${styleName}" | Influence: ${percentage}% | Visuals: ${keywords}`);
      } else {
          // Negative application (Avoidance) with granular weight
          negativeStyleDirectives.push(`   - Avoid Style: "${styleName}" | Strictness: ${percentage}% | Exclude: ${keywords}`);
      }
  };

  processStyleAxis(styleA, matrixX);
  processStyleAxis(styleB, matrixY);

  if (styleDirectives.length > 0) {
      sections.push(`[STYLE MIXING]
The AI should blend the following styles according to their exact percentage influence (0-100%):
${styleDirectives.join('\n')}`);
  }

  if (negativeStyleDirectives.length > 0) {
       sections.push(`[STYLE EXCLUSIONS]
The AI must actively avoid these specific style elements with the specified strictness (0-100%):
${negativeStyleDirectives.join('\n')}`);
  }

  // 3. ATMOSPHERE & TECHNICAL
  const atmosphere: string[] = [];

  if (lighting && LIGHTING_PROMPTS[lighting]) {
      atmosphere.push(`Lighting: ${LIGHTING_PROMPTS[lighting]}`);
  }

  if (depthOfField && DEPTH_PROMPTS[depthOfField]) {
      atmosphere.push(`Depth of Field: ${DEPTH_PROMPTS[depthOfField]}`);
  }

  if (colorPalette && COLOR_PALETTE_PROMPTS[colorPalette]) {
      atmosphere.push(`Color Palette: ${COLOR_PALETTE_PROMPTS[colorPalette]}`);
  }

  if (atmosphere.length > 0) {
      sections.push(`[ATMOSPHERE & TECHNICAL SPECS]\n${atmosphere.join(' | ')}`);
  }

  // 4. NEGATIVE CONSTRAINTS
  const allNegatives = [...negativePrompts];
  if (allNegatives.length > 0) {
      sections.push(`[GLOBAL NEGATIVE PROMPTS]\n${allNegatives.join(', ')}`);
  }

  // 5. GLOBAL QUALITY SEAL
  sections.push(`[QUALITY STANDARDS]\nHigh fidelity, detailed textures, professional composition, coherent lighting, masterpiece.`);

  return sections.join('\n\n');
};

interface GenerationResult {
    url: string;
    point: Point;
}

export const generateImages = async (params: GenerationParams): Promise<GenerationResult[]> => {
  // Use VITE_GEMINI_API_KEY from import.meta.env
  // Fallback to VITE_API_KEY if needed.
  // Fix: safely access env property
  const env = (import.meta as any).env;
  const apiKey = env?.VITE_GEMINI_API_KEY || env?.VITE_API_KEY;

  if (!apiKey) {
      throw new Error("API Key not found. Please set VITE_GEMINI_API_KEY in your Vercel Project Settings.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const tasks: { point: Point }[] = [];

  if (params.matrixPoints.length > 1) {
    params.matrixPoints.forEach((point) => {
        tasks.push({ point });
    });
  } else {
    const point = params.matrixPoints[0] || { x: 0, y: 0 };
    for (let i = 0; i < params.imageCount; i++) {
        tasks.push({ point });
    }
  }

  const promises = tasks.map(async (task) => {
    const finalPrompt = constructEnrichedPrompt(params, task.point);
    const config: any = { 
        imageConfig: {
            aspectRatio: params.aspectRatio
        }
    };

    // Pass seed if custom seed is enabled
    if (params.useCustomSeed) {
        config.seed = params.seed;
    }

    if (params.model === ModelOption.PRO) {
        config.imageConfig.imageSize = "1K";
    }

    try {
      const parts: any[] = [{ text: finalPrompt }];

      if (params.uploadedImage) {
        parts.unshift({
          inlineData: {
            data: extractBase64Data(params.uploadedImage),
            mimeType: getMimeType(params.uploadedImage),
          }
        });
      }

      const response = await ai.models.generateContent({
        model: params.model,
        contents: { parts },
        config
      });

      if (response?.candidates?.[0]?.content?.parts) {
         for (const part of response.candidates[0].content.parts) {
            if (part.inlineData && part.inlineData.data) {
               return {
                 url: `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`,
                 point: task.point
               };
            }
         }
      }
      throw new Error("Model returned no image data.");
    } catch (error: any) {
      // Propagate error message to UI
      throw new Error(error.message || "Failed to generate image.");
    }
  });

  // Use allSettled to allow partial success in a batch
  const results = await Promise.allSettled(promises);

  const successfulImages: GenerationResult[] = [];
  let errorMsg = "";

  results.forEach(result => {
      if (result.status === 'fulfilled') {
          successfulImages.push(result.value);
      } else {
          errorMsg = result.reason.message;
      }
  });

  if (successfulImages.length === 0 && errorMsg) {
      throw new Error(errorMsg);
  }

  return successfulImages;
};

import React from 'react';
import { Fuel } from 'lucide-react';
import { GenerationParams } from '../types';
import { STYLE_PROMPTS, LIGHTING_PROMPTS, DEPTH_PROMPTS, COLOR_PALETTE_PROMPTS } from '../services/geminiService';

interface TokenFuelGaugeProps {
  params: GenerationParams;
}

export const TokenFuelGauge: React.FC<TokenFuelGaugeProps> = ({ params }) => {
  // Approximate calculations
  // Gemini approx: 1 token ~= 4 chars

  // 1. Core Prompt
  const promptTokens = Math.ceil(params.prompt.length / 4);

  // 2. Image (Fixed cost for Flash/Pro image inputs)
  const imageTokens = params.uploadedImage ? 258 : 0; 

  // 3. Styles (Axis A & Axis B)
  // Even if not triggered by the matrix point in the UI, we count them as potential load
  const styleATokens = Math.ceil((STYLE_PROMPTS[params.styleA] || "").length / 4);
  const styleBTokens = Math.ceil((STYLE_PROMPTS[params.styleB] || "").length / 4);

  // 4. Technical Params
  const lightingTokens = Math.ceil((LIGHTING_PROMPTS[params.lighting] || "").length / 4);
  const depthTokens = Math.ceil((DEPTH_PROMPTS[params.depthOfField] || "").length / 4);
  const paletteTokens = Math.ceil((COLOR_PALETTE_PROMPTS[params.colorPalette] || "").length / 4);

  // 5. Negative Prompts
  // Joined by comma space
  const negativeTokens = Math.ceil((params.negativePrompts.join(", ") || "").length / 4);

  // 6. Overhead (System prompts headers like [SUBJECT], [QUALITY STANDARDS] etc)
  const overheadTokens = 60; 

  const totalTokens = promptTokens + imageTokens + styleATokens + styleBTokens + lightingTokens + depthTokens + paletteTokens + negativeTokens + overheadTokens;

  // Visual scale: Arbitrary "standard prompt" size for visualization
  // 3000 is a safe buffer for Gemini 2.5 Flash Image which has large context, but we want the bar to move visibly.
  const MAX_DISPLAY = 3000;
  const percentage = Math.min((totalTokens / MAX_DISPLAY) * 100, 100);

  // Color logic
  let colorClass = "bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.4)]";
  if (totalTokens > 1500) colorClass = "bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.4)]";
  if (totalTokens > 2500) colorClass = "bg-red-500 shadow-[0_0_10px_rgba(239,68,68,0.4)]";

  return (
    <div className="flex items-center gap-2 px-3 py-1.5 bg-zinc-900/50 rounded-lg border border-zinc-800/50 backdrop-blur-sm select-none" title={`Approximate Context: ${totalTokens} tokens (Prompt: ${promptTokens}, Styles: ${styleATokens + styleBTokens}, Params: ${lightingTokens + depthTokens + paletteTokens + negativeTokens})`}>
      <Fuel className={`w-3.5 h-3.5 ${totalTokens > 0 ? 'text-zinc-300' : 'text-zinc-600'}`} />
      <span className="text-[10px] font-mono text-zinc-400 w-8 text-right">{totalTokens}</span>
      <div className="w-20 h-1.5 bg-zinc-800 rounded-full overflow-hidden relative">
        <div 
            className={`h-full transition-all duration-500 ease-out rounded-full ${colorClass}`} 
            style={{ width: `${Math.max(5, percentage)}%` }}
        />
      </div>
    </div>
  );
};

